  /** Small, safe Markdown: everything is text nodes; only http(s) links become links. */
  function renderMarkdown(src) {
    const frag = document.createDocumentFragment();
    const lines = String(src || '').replace(/\r/g, '').split('\n');
    let list = null;
    let para = null;
    const inline = (parent, text) => {
      const re = /(\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|\[[^\]]+\]\((https?:\/\/[^)\s]+)\)|https?:\/\/[^\s)]+|\*[^*\s][^*]*\*)/g;
      let last = 0;
      let m;
      while ((m = re.exec(text))) {
        if (m.index > last) parent.append(text.slice(last, m.index));
        const tok = m[0];
        if (tok.startsWith('**') || tok.startsWith('__')) parent.append(el('b', { text: tok.slice(2, -2) }));
        else if (tok.startsWith('`')) parent.append(el('code', { text: tok.slice(1, -1) }));
        else if (tok.startsWith('[')) {
          const label = tok.slice(1, tok.indexOf(']'));
          parent.append(link(label, m[2]));
        } else if (/^https?:/.test(tok)) parent.append(link(tok.replace(/^https?:\/\/(www\.)?/, '').slice(0, 40), tok));
        else parent.append(el('i', { text: tok.slice(1, -1) }));
        last = m.index + tok.length;
      }
      if (last < text.length) parent.append(text.slice(last));
    };
    const link = (label, url) => el('a', { href: '#', onclick: (e) => { e.preventDefault(); app.openTab(url, { keepScreen: false }); } }, label);
    lines.forEach((raw) => {
      const line = raw.trimEnd();
      const bullet = /^\s*([-*•]|\d+[.)])\s+(.*)$/.exec(line);
      const heading = /^\s*#{1,4}\s+(.*)$/.exec(line);
      if (bullet) {
        const ordered = /\d/.test(bullet[1]);
        if (!list || list.tagName !== (ordered ? 'OL' : 'UL')) {
          list = el(ordered ? 'ol' : 'ul');
          frag.append(list);
        }
        const li = el('li');
        inline(li, bullet[2]);
        list.append(li);
        para = null;
        return;
      }
      list = null;
      if (!line.trim()) {
        para = null;
        return;
      }
      if (heading) {
        const h = el('div', { class: 'md-h' });
        inline(h, heading[1]);
        frag.append(h);
        para = null;
        return;
      }
      if (!para) {
        para = el('p');
        frag.append(para);
      } else {
        para.append(el('br'));
      }
      inline(para, line);
    });
    return frag;
  }

  function listenButton(item) {
    const owner = 'ai:' + item.id;
    const on = app.speech && app.speech().owner === owner;
    return el('button', { class: 'mini' + (on ? ' on' : ''), 'data-listen': owner, onclick: () => {
      haptic();
      app.speakText(owner, C.plainText(item.text));
    } }, icon(on ? 'stopsq' : 'speaker'), on ? 'Stop' : 'Listen');
  }

  function bubbleFor(item) {
    // New messages slide in once; ones already on screen stay put when the chat redraws.
    const enter = item.shown ? '' : ' enter';
    item.shown = true;
    if (!item.id) item.id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    if (item.kind === 'user') {
      return el('div', { class: 'ai-msg user' + enter + (item.voice ? ' voice' : '') },
        el('div', { class: 'bubble' }, item.voice ? el('span', { class: 'said' }, icon('mic')) : null, item.text));
    }
    if (item.kind === 'step') {
      return el('div', { class: 'ai-step' + enter + (item.done ? ' done' : '') + (item.failed ? ' failed' : '') },
        el('span', { class: 'step-dot' }), el('span', { text: item.text }));
    }
    if (item.kind === 'error') return el('div', { class: 'ai-msg error' + enter }, el('div', { class: 'bubble', text: item.text }));
    const b = el('div', { class: 'bubble md' });
    if (item.text) b.append(renderMarkdown(item.text));
    else b.append(el('span', { class: 'typing' }, el('i'), el('i'), el('i')));
    const msg = el('div', { class: 'ai-msg ai' + enter }, b);
    if (item.text && !busy) {
      const tools = el('div', { class: 'ai-tools' },
        el('button', { class: 'mini', onclick: () => { N.copy(item.text); toast('Copied'); } }, icon('copy'), 'Copy'));
      if (app.speakText) tools.append(listenButton(item));
      msg.append(tools);
    }
    item.node = b;
    return msg;
  }

  function refreshListenButtons() {
    $$('#ai-body [data-listen]').forEach((btn) => {
      const item = view.find((v) => 'ai:' + v.id === btn.getAttribute('data-listen'));
      if (item) btn.replaceWith(listenButton(item));
    });
    window.fillIcons($('#ai-body'));
  }

  function updateBubble(item) {
    if (!item.node || !item.node.isConnected) return renderChat();
    item.node.textContent = '';
    item.node.append(renderMarkdown(item.text));
    scrollDown();
  }

  function scrollDown() {
    const body = $('#ai-body');
    body.scrollTop = body.scrollHeight;
  }

  function renderChat() {
    const body = $('#ai-body');
    body.textContent = '';
    $('#ai-form').hidden = false;
    const p = P();
    $('#ai-provider').textContent = builtinKey ? 'Free' : p ? p.name : 'Set up';
    if (!view.length) {
      body.append(welcomeCard());
    } else {
      view.forEach((item) => body.append(bubbleFor(item)));
    }
    window.fillIcons(body);
    renderChips();
    scrollDown();
  }

