      el('p', { text: t ? 'Ask me about this page, or tell me what to do: open sites, search, switch tabs…' : 'Ask me anything, or tell me what to do: open sites, search the web, start Focus mode…' }),
      el('p', { class: 'ai-private', text: '🔒 Your chats stay on this ' + device + '. Nobody else can see them.' }));
    if (P() && !P().tools) card.append(el('p', { class: 'ai-note', text: 'Basic mode can read pages but can’t open tabs. Connect a free Groq or Gemini key in TP AI settings for the full assistant.' }));
