  function setup() {
    const q = $('#ai-q');
    const grow = () => {
      q.style.height = 'auto';
      q.style.height = Math.min(120, q.scrollHeight) + 'px';
    };
    q.addEventListener('input', () => {
      grow();
      syncSendButton();
    });
    q.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        $('#ai-form').requestSubmit();
      }
    });
    $('#ai-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const text = q.value;
      if (!text.trim()) return;
      q.value = '';
      grow();
      // On the Mac the mic starts the system's Dictation; that question gets a spoken answer too.
      ask(text, { voice: !!(app.consumeVoice && app.consumeVoice()) });
    });
    $('#ai-mic').onclick = () => {
      haptic();
      q.blur();
      if (app.speech && app.speech().playing) app.stopSpeech();
      app.voice('ai');
    };
    if (app.onSpeech) app.onSpeech(() => {
      if (!$('#ai').hidden) refreshListenButtons();
    });
    syncSendButton();
    $('#ai-stop').onclick = () => stop();
    $('#ai-new').onclick = () => newChat();
    $('#ai-settings').onclick = () => renderSetup(provider());
    $('#ai-close').onclick = () => app.closeScreen();
    $('#ai-scrim').onclick = () => app.closeScreen();
    $('#ai-provider').onclick = () => renderSetup(provider());
    window.fillIcons($('#ai'));
  }

  return {
    PROVIDERS,
    setup,
    open,
    ask,
    stop,
    newChat,
    renderSetup,
    isBusy: () => busy,
    isBuiltin: () => !!builtinKey,
    provider,
    providerName: () => (builtinKey ? 'TP AI' : P() ? P().name : ''),
    disconnect() {
      cfg.provider = null;
      app.saveSettings();
    },
    // exposed for tests
    _makeStreamParser: makeStreamParser,
    _renderMarkdown: renderMarkdown,
    _pickModels: pickModels,
    _runTool: runTool,
  };
};

