'use strict';
/* TP Browser for Android: the interface (address bar, home, tabs, menus, settings).
 * Websites live in native WebViews behind this page; TPNative is the bridge to them. */
(function () {
  const C = window.TPCore;
  const N = window.TPNative || makeMockNative();
  const $ = (s, root) => (root || document).querySelector(s);
  const $$ = (s, root) => Array.from((root || document).querySelectorAll(s));

  // ------------------------------------------------------------------------------------------
  // Small helpers
  // ------------------------------------------------------------------------------------------

  function el(tag, props) {
    const e = document.createElement(tag);
    if (props) {
      for (const k of Object.keys(props)) {
        const v = props[k];
        if (v == null || v === false) continue;
        if (k === 'class') e.className = v;
        else if (k === 'text') e.textContent = v;
        else if (k === 'html') e.innerHTML = v;
        else if (k === 'style') e.style.cssText = v;
        else if (k.slice(0, 2) === 'on') e.addEventListener(k.slice(2), v);
        else e.setAttribute(k, v === true ? '' : v);
      }
    }
    for (let i = 2; i < arguments.length; i++) append(e, arguments[i]);
    return e;
  }

  function append(parent, kid) {
    if (kid == null || kid === false) return;
    if (Array.isArray(kid)) kid.forEach((k) => append(parent, k));
    else parent.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
  }

  function icon(name) {
    const s = document.createElement('span');
    s.innerHTML = window.ICONS[name] || '';
    return s.firstChild || s;
  }

  function hue(text) {
    let h = 0;
    for (const ch of String(text || '?')) h = (h * 31 + ch.charCodeAt(0)) % 360;
    return h;
  }

  function letterColor(text) {
    const h = hue(text);
    return 'linear-gradient(135deg, hsl(' + h + ' 70% 58%), hsl(' + ((h + 40) % 360) + ' 70% 48%))';
  }

  function siteLetter(host, title) {
    const s = (C.rootDomain(host) || title || '?').replace(/^www\./, '');
    return (s[0] || '?').toUpperCase();
  }

  function faviconFor(url) {
    const host = C.hostOf(url);
    if (!host) return null;
    return favicons[host] || favicons[C.rootDomain(host)] || null;
  }

  /** A favicon image, falling back to a coloured letter. */
  function siteIcon(url, title, cls, remoteFallback, titleLetter) {
    const host = C.hostOf(url);
    const data = faviconFor(url);
    const box = el('span', { class: cls });
    const letter = () => {
      box.textContent = titleLetter && title ? title.trim()[0].toUpperCase() : siteLetter(host, title);
      box.classList.add('letter');
      box.style.background = letterColor(host || title);
    };
    if (data || (remoteFallback && host)) {
      const img = el('img', { alt: '', src: data || 'https://icons.duckduckgo.com/ip3/' + host + '.ico' });
      img.onerror = () => {
        img.remove();
        letter();
      };
      box.append(img);
    } else {
      letter();
    }
    return box;
  }

  /** kind: undefined (tap), "tick" (light), "confirm", "reject", "long". */
  function haptic(kind) {
    try {
      if (kind && N.hapticKind) N.hapticKind(kind);
      else N.haptic();
    } catch (e) {
      // older bridge
    }
  }

  let deviceInfo = null;
  function device() {
    if (!deviceInfo) {
      try {
        deviceInfo = JSON.parse(N.info() || '{}');
      } catch (e) {
        deviceInfo = {};
      }
    }
    return deviceInfo;
  }

  function toast(text) {
    N.toast(text);
  }

  /** TP Browser for iPhone and iPad shares this interface; a few words and options differ there. */
  const IOS = window.TP_PLATFORM === 'ios';
  function deviceWord() {
    return IOS ? device().device || 'iPhone' : 'phone';
  }
  const canDefault = () => device().canDefault !== false;
  if (IOS) {
    // Liquid Glass (glass.css). ios-edge: the app lets this page reach the bottom edge of the screen.
    document.documentElement.classList.add('ios');
    if (Number(device().build) >= 2) document.documentElement.classList.add('ios-edge');
  }
  // iOS 26 and newer (app build 3+): the app draws the address bar itself in Apple's real Liquid Glass. This page
  // tells it what to show (syncNativeBar) and does what its buttons do (barAction).
  const NATIVE_BAR = IOS && !!device().nativeBar;
  if (NATIVE_BAR) document.documentElement.classList.add('ios-native-bar');

  // ------------------------------------------------------------------------------------------
  // Storage (files in the app's private folder, through the bridge)
  // ------------------------------------------------------------------------------------------

  function load(key, fallback) {
    try {
      const s = N.load(key);
      return s ? JSON.parse(s) : fallback;
    } catch (e) {
      return fallback;
    }
  }

  const saveTimers = {};
  const saveGetters = {};

  function saveSoon(key, getter, ms) {
    saveGetters[key] = getter;
    clearTimeout(saveTimers[key]);
    saveTimers[key] = setTimeout(() => saveNow(key), ms || 600);
  }

  function saveNow(key) {
    clearTimeout(saveTimers[key]);
    delete saveTimers[key];
    const g = saveGetters[key];
    if (g) N.save(key, JSON.stringify(g()));
  }

  function flushSaves() {
    Object.keys(saveTimers).forEach(saveNow);
  }

  // ------------------------------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------------------------------

  const DEFAULT_SPACES = [
    { id: 'personal', name: 'Personal', icon: '🏠', color: 'violet' },
    { id: 'school', name: 'School', icon: '📚', color: 'blue' },
    { id: 'games', name: 'Games', icon: '🎮', color: 'green' },
  ];
  const SPACE_ICONS = ['🏠', '📚', '🎮', '💼', '🎨', '🎵', '🌏', '🧪', '⚽', '🍜', '🚀', '💡', '🛒', '✈️', '🐱', '🌱', '🎬', '💻'];
  const DEFAULT_FOCUS_SITES = ['youtube.com', 'tiktok.com', 'instagram.com', 'facebook.com', 'x.com', 'twitter.com', 'reddit.com', 'netflix.com', 'twitch.tv', 'roblox.com'];
  const DEFAULT_SETTINGS = {
    name: '',
    onboarded: false,
    searchEngine: 'google',
    suggestions: true,
    restoreTabs: true,
    shield: true,
    ytSkip: true,
    shieldAllow: [],
    sleepAfter: 30,
    focusMinutes: 25,
    focusSites: DEFAULT_FOCUS_SITES,
    focusStartedAt: 0,
    focusEndsAt: 0,
    city: { name: 'Bangkok', region: 'Bangkok', country: 'Thailand', lat: 13.7563, lon: 100.5018 },
    tempUnit: 'C',
    wallpaper: 'space',
    textZoom: 100,
    note: '',
    spaces: DEFAULT_SPACES,
    darkPages: false,
    darkExcept: [],
    pipAuto: true,
    voiceLang: '',
    speechRate: 1,
    translateTo: '',
  };
  const READER_SIZES = [15, 16, 17, 18, 19, 20, 22, 24, 26, 28];
  const READER_THEMES = { light: '#fbfaf7', sepia: '#f4ecd8', dark: '#17161c' };
  const LANGUAGES = [
    ['en', 'English', 'EN'],
    ['th', 'ไทย', 'TH'],
    ['zh-CN', '中文', '中'],
    ['ja', '日本語', 'JA'],
    ['ko', '한국어', 'KO'],
    ['es', 'Español', 'ES'],
    ['fr', 'Français', 'FR'],
    ['de', 'Deutsch', 'DE'],
  ];
  const DEFAULT_FAVORITES = [
    { url: 'https://www.google.com/', title: 'Google' },
    { url: 'https://www.youtube.com/', title: 'YouTube' },
    { url: 'https://mail.google.com/', title: 'Gmail' },
    { url: 'https://classroom.google.com/', title: 'Classroom' },
    { url: 'https://www.wikipedia.org/', title: 'Wikipedia' },
    { url: 'https://translate.google.com/', title: 'Translate' },
    { url: 'https://www.instagram.com/', title: 'Instagram' },
    { url: 'https://maps.google.com/', title: 'Maps' },
  ];
  const WALLPAPERS = [
    { id: 'space', name: 'TP', top: null, bottom: null },
    { id: 'aurora', name: 'Aurora', top: '#1e1b4b', bottom: '#0f766e' },
    { id: 'sunset', name: 'Sunset', top: '#3b1673', bottom: '#f97316' },
    { id: 'ocean', name: 'Ocean', top: '#0c2d6b', bottom: '#06b6d4' },
    { id: 'forest', name: 'Forest', top: '#052e16', bottom: '#4d7c0f' },
    { id: 'midnight', name: 'Midnight', top: '#0b1026', bottom: '#312e81' },
    { id: 'custom', name: 'Photo', top: '#000000', bottom: '#000000' },
  ];
  const NO_BAR_SCREENS = new Set(['search', 'tabs', 'history', 'settings', 'favorites', 'welcome', 'ai', 'reader']);
  const SCREENS = ['search', 'tabs', 'history', 'settings', 'favorites', 'welcome', 'ai', 'reader'];
  const BUILD = window.TP_BUILD || { version: '', versionCode: 0, updateUrl: '' };
  const MAX_LIVE_TABS = 6;

  const settings = Object.assign({}, DEFAULT_SETTINGS, load('settings', {}));
  if (!Array.isArray(settings.spaces) || !settings.spaces.length) settings.spaces = DEFAULT_SPACES.slice();
  if (!Array.isArray(settings.darkExcept)) settings.darkExcept = [];
  settings.reader = Object.assign({ size: 19, font: 'serif', theme: 'auto' }, settings.reader || {});
  let bookmarks = load('bookmarks', null);
  if (!Array.isArray(bookmarks)) bookmarks = DEFAULT_FAVORITES.slice();
  let history = load('history', []);
  if (!Array.isArray(history)) history = [];
  const stats = Object.assign({ blocked: {}, focus: {} }, load('stats', {}));
  let favicons = load('favicons', {}) || {};
  let weather = load('weather', null);
  let wallpaperPhoto = load('wallpaper', '');

  let tabs = [];
  let activeId = null;
  let space = settings.spaces[0].id;
  let activeBySpace = {};
  let screen = null;
  let sheet = null;
  let tabsViewSpace = null;
  let findOpen = false;
  let barH = 64;
  let lastModeSig = '';
  let dark = window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
  let isDefaultBrowser = false;
  const closedTabs = [];

  const saveSettings = () => saveSoon('settings', () => settings);
  const saveBookmarks = () => saveSoon('bookmarks', () => bookmarks);
  const saveHistory = () => saveSoon('history', () => history, 1500);
  const saveStats = () => saveSoon('stats', () => stats, 1500);
  const saveFavicons = () => saveSoon('favicons', () => favicons, 3000);
  const saveSession = () =>
    saveSoon('session', () => ({
      v: 1,
      space,
      activeBySpace,
      tabs: tabs.filter((t) => !t.hidden).map((t) => ({
        id: t.id,
        space: t.space,
        url: t.home && !t.live ? '' : C.realUrl(t.url) || t.url || '',
        title: t.title || '',
        home: !!t.home,
        desktop: !!t.desktop,
        fromHome: !!t.fromHome,
      })),
    }));

  const tab = (id) => tabs.find((t) => t.id === id) || null;
  const activeTab = () => tab(activeId);
  const spaceById = (id) => settings.spaces.find((s) => s.id === id) || null;
  const tabsIn = (sp) => tabs.filter((t) => t.space === sp && !t.hidden);
  const pageTab = () => {
    const t = activeTab();
    return t && !t.home && t.url ? t : null;
  };
  const onHome = () => {
    const t = activeTab();
    return !t || !!t.home;
  };
  const focusActive = () => settings.focusEndsAt > Date.now();
  const isBookmarked = (url) => bookmarks.some((b) => b.url === url);
  const shieldOnFor = (url) => settings.shield && !C.hostInList(C.hostOf(url), settings.shieldAllow);

  function newTabId() {
    return 't' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  }

  // ------------------------------------------------------------------------------------------
  // Look: theme, space colours, wallpaper
  // ------------------------------------------------------------------------------------------

  function applyTheme() {
    document.documentElement.classList.toggle('dark', dark);
  }

  function applySpaceColors() {
    const sp = spaceById(space) || settings.spaces[0];
    const colors = C.SPACE_COLORS[sp.color] || C.SPACE_COLORS.violet;
    document.documentElement.style.setProperty('--c1', colors[0]);
    document.documentElement.style.setProperty('--c2', colors[1]);
  }

  function applyWallpaper() {
    const wp = settings.wallpaper === 'custom' && !wallpaperPhoto ? 'space' : settings.wallpaper;
    WALLPAPERS.forEach((w) => document.body.classList.toggle('wp-' + w.id, w.id === wp));
    document.body.classList.toggle('vivid', wp !== 'space');
    $('#wall').style.backgroundImage = wp === 'custom' ? 'url("' + wallpaperPhoto + '")' : '';
  }

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function homeBottomColor() {
    const wp = WALLPAPERS.find((w) => w.id === settings.wallpaper);
    if (wp && wp.bottom && (wp.id !== 'custom' || wallpaperPhoto)) return wp.bottom;
    return cssVar('--bg');
  }

  function homeStatusColor() {
    const wp = WALLPAPERS.find((w) => w.id === settings.wallpaper);
    if (wp && wp.top && (wp.id !== 'custom' || wallpaperPhoto)) return wp.top;
    return cssVar('--bg');
  }

  // ------------------------------------------------------------------------------------------
  // Full screen vs. bar: the interface WebView is either the whole screen or just the bar
  // ------------------------------------------------------------------------------------------

  function isFull() {
    return !!screen || !!sheet || closing > 0 || onHome();
  }

  // ------------------------------------------------------------------------------------------
  // Motion. Enter animations wait until the interface fills the screen (the native side resizes
  // it), and exit animations finish before it shrinks back to the bar, so nothing jumps.
  // ------------------------------------------------------------------------------------------

  let closing = 0;
  let closingScreen = null;
  const reducedMotion = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  function whenFull(fn) {
    const big = () => window.innerHeight > (NATIVE_BAR ? 200 : barH * 2.5);
    if (big()) return requestAnimationFrame(fn);
    let done = false;
    const go = () => {
      if (done) return;
      done = true;
      window.removeEventListener('resize', onResize);
      requestAnimationFrame(fn);
    };
    const onResize = () => {
      if (big()) go();
    };
    window.addEventListener('resize', onResize);
    setTimeout(go, 300);
  }

  function animateIn(elm) {
    if (!elm || reducedMotion) return;
    elm.classList.remove('anim-out', 'anim-in');
    elm.classList.add('anim-wait');
    whenFull(() => {
      elm.classList.remove('anim-wait');
      void elm.offsetWidth;
      elm.classList.add('anim-in');
      const clear = () => {
        elm.removeEventListener('animationend', onEnd);
        elm.classList.remove('anim-in');
      };
      // Only the element's own animation counts (tab cards inside animate a little longer).
      const onEnd = (e) => {
        if (e.target === elm) clear();
      };
      elm.addEventListener('animationend', onEnd);
      setTimeout(clear, 1100);
    });
  }

  function animateOut(elm, then) {
    if (!elm || reducedMotion || elm.hidden) return then();
    closing++;
    elm.classList.remove('anim-in', 'anim-wait');
    elm.classList.add('anim-out');
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      elm.classList.remove('anim-out');
      closing = Math.max(0, closing - 1);
      then();
    };
    elm.addEventListener('animationend', finish, { once: true });
    setTimeout(finish, 320);
  }

  // The home page plays its entrance when it appears from a website or for a different tab,
  // not when you just close the search screen over it.
  let homeWasVisible = false;
  let homeShownFor = null;
  let wasFull = false;

  function cascadeHome() {
    if (reducedMotion) return;
    const h = $('#home');
    h.classList.remove('home-enter');
    whenFull(() => {
      void h.offsetWidth;
      h.classList.add('home-enter');
      clearTimeout(h._enterTimer);
      h._enterTimer = setTimeout(() => h.classList.remove('home-enter'), 1000);
    });
  }

  function syncMode() {
    const full = isFull();
    const body = document.body;
    body.classList.toggle('full', full);
    body.classList.toggle('on-home', onHome() && !screen);
    body.classList.toggle('no-bar', NO_BAR_SCREENS.has(screen));
    const homeVisible = onHome() && (!screen || screen === 'ai' || !NO_BAR_SCREENS.has(screen));
    $('#home').hidden = !homeVisible;
    if (homeVisible && !homeWasVisible && (!wasFull || homeShownFor !== activeId)) cascadeHome();
    homeWasVisible = homeVisible;
    if (homeVisible) homeShownFor = activeId;
    wasFull = full;
    SCREENS.forEach((id) => {
      $('#' + id).hidden = screen !== id && closingScreen !== id;
    });
    const measured = $('#bar').offsetHeight;
    if (measured > 0 || NATIVE_BAR) barH = measured;

    let status = '';
    let nav = cssVar('--bar');
    if (screen === 'reader' || (!screen && closingScreen === 'reader')) {
      status = readerBg();
      nav = status;
    } else if (screen === 'ai') {
      status = onHome() ? homeStatusColor() : '';
      nav = cssVar('--sheet');
    } else if (screen && screen !== 'search' && screen !== 'tabs') {
      status = cssVar('--bg');
      nav = cssVar('--bg');
    } else if (screen) {
      status = cssVar('--bg');
    } else if (onHome()) {
      status = homeStatusColor();
    }
    if (sheet) nav = cssVar('--sheet');
    if (IOS && screen !== 'reader' && (!screen || screen === 'ai')) {
      // The glass bar floats: around it the page's own colour shows (the app picks it: "page"), or the wallpaper.
      if (onHome()) nav = homeBottomColor();
      else nav = Number(device().build) >= 2 ? 'page' : cssVar('--bg');
    }
    const sig = [full ? 'full' : 'bar', barH, status, nav].join('|');
    if (sig !== lastModeSig) {
      lastModeSig = sig;
      N.setUiMode(full ? 'full' : 'bar', barH, status, nav);
    }
    syncNativeBar();
  }

  let lastBarSig = '';
  function syncNativeBar() {
    if (!NATIVE_BAR) return;
    const t = activeTab();
    const st = { label: 'Search or type URL', placeholder: false, warn: false, search: false, icon: 'search', insecure: false, count: '', reload: 'hidden', progress: -1 };
    if (!t || t.home || !t.url) {
      st.placeholder = true;
    } else {
      const real = C.realUrl(t.url) || t.url;
      const d = C.displayUrl(real);
      if (d.search) {
        st.label = d.search;
        st.search = true;
      } else {
        st.label = d.text || real;
        if (/^http:/i.test(real)) {
          st.warn = true;
          st.insecure = true;
        }
      }
      const on = shieldOnFor(real);
      st.icon = on ? 'shield' : 'shieldOff';
      if (on && t.blocked > 0) st.count = t.blocked > 99 ? '99+' : String(t.blocked);
      st.reload = t.loading ? 'stop' : 'reload';
      if (t.loading) st.progress = Math.max(8, t.progress || 0);
    }
    st.focus = focusActive();
    st.tabs = $('#tab-count').textContent;
    st.tinted = space !== settings.spaces[0].id;
    st.prev = !!neighbourTab(-1);
    st.next = !!neighbourTab(1);
    st.accent = cssVar('--c1');
    st.dark = document.documentElement.classList.contains('dark');
    // Shown where this page's own bar would be; menus, screens and the find bar have it step aside.
    st.show = !screen && !sheet && closing === 0 && $('#findbar').hidden && !document.body.classList.contains('no-bar');
    const sig = JSON.stringify(st);
    if (sig === lastBarSig) return;
    lastBarSig = sig;
    N.setBar(st);
  }

  /** A tap on the app's glass bar: the same as tapping this page's own button. */
  function barAction(e) {
    const ids = { back: '#b-back', pill: '#pill-text', shield: '#pill-shield', reload: '#pill-reload', ai: '#b-ai', tabs: '#b-tabs', menu: '#b-menu' };
    if (ids[e.action]) return $(ids[e.action]).click();
    if (e.action === 'newtab') {
      haptic();
      openTab('');
    } else if (e.action === 'swipe') {
      swipeToTab(e.dir > 0 ? 1 : -1);
    }
  }

  function update() {
    renderBar();
    syncMode();
    if (!$('#home').hidden) renderHome();
    if (screen === 'tabs') renderTabs();
  }

  // ------------------------------------------------------------------------------------------
  // Tabs
  // ------------------------------------------------------------------------------------------

  function makeTab(props) {
    return Object.assign(
      { id: newTabId(), space, url: '', title: '', home: true, opener: null, external: false, fromHome: false, desktop: false, live: false, lastActive: Date.now(), back: false, fwd: false, loading: false, progress: 0, secure: false, blocked: 0, thumb: null },
      props
    );
  }

  function insertTab(t, afterId) {
    const i = afterId ? tabs.findIndex((x) => x.id === afterId) : -1;
    if (i >= 0) tabs.splice(i + 1, 0, t);
    else tabs.push(t);
  }

  /** Make sure a page tab has a WebView, and optionally show it. */
  function ensureLive(t, show) {
    if (t.home) {
      if (show) N.showTab('');
      return;
    }
    if (!t.live) {
      t.live = true;
      t.back = false;
      t.fwd = false;
      N.createTab(t.id, C.realUrl(t.url) || t.url, show, !!t.desktop);
    } else if (show) {
      N.showTab(t.id);
    }
    if (show) enforceLiveLimit();
  }

  function sleepTab(t) {
    if (!t.live) return;
    N.closeTab(t.id);
    t.live = false;
    t.back = false;
    t.fwd = false;
    t.loading = false;
  }

  function enforceLiveLimit() {
    const live = tabs.filter((t) => t.live && t.id !== activeId).sort((a, b) => a.lastActive - b.lastActive);
    while (live.length > MAX_LIVE_TABS - 1) sleepTab(live.shift());
  }

  /** dir (optional): 1 or -1 slides the page in sideways, for swiping between tabs. */
  function activate(id, dir) {
    const t = tab(id);
    if (!t) return;
    const prev = activeTab();
    if (prev && prev.id !== id && prev.live && !prev.home) N.thumbnail(prev.id);
    activeId = id;
    t.lastActive = Date.now();
    if (t.space !== space) {
      space = t.space;
      applySpaceColors();
    }
    activeBySpace[space] = id;
    closeFind();
    if (t.home) N.showTab('');
    else if (dir && t.live && N.showTabSlide && prev && !prev.home) {
      N.showTabSlide(t.id, dir);
      enforceLiveLimit();
    } else ensureLive(t, true);
    saveSession();
  }

  function openTab(url, opts) {
    opts = opts || {};
    const sp = opts.space || space;
    const t = makeTab({ space: sp, url: url || '', home: !url, opener: opts.opener || null, external: !!opts.external, hidden: !!opts.hidden, loading: !!url });
    insertTab(t, opts.after || (opts.opener ? opts.opener : null));
    if (url && opts.background) {
      ensureLive(t, false);
    }
    if (!opts.background) activate(t.id);
    saveSession();
    update();
    return t;
  }

  function closeTab(id) {
    const i = tabs.findIndex((t) => t.id === id);
    if (i < 0) return;
    const t = tabs[i];
    if (t.live) N.closeTab(id);
    tabs.splice(i, 1);
    if (t.hidden) return;
    if (t.url && !t.home) {
      closedTabs.push({ url: C.realUrl(t.url) || t.url, space: t.space });
      if (closedTabs.length > 15) closedTabs.shift();
    }
    if (activeId === id) {
      activeId = null;
      const same = tabsIn(t.space);
      let pick = t.opener ? tab(t.opener) : null;
      if (pick && pick.space !== t.space) pick = null;
      if (!pick && same.length) {
        const after = tabs.slice(i).find((x) => x.space === t.space);
        pick = after || same[same.length - 1];
      }
      if (pick) activate(pick.id);
      else openTab('', { space: t.space });
    }
    if (activeBySpace[t.space] === id) delete activeBySpace[t.space];
    saveSession();
    update();
  }

  function goHome(t, destroy) {
    t.home = true;
    if (destroy) {
      sleepTab(t);
      t.url = '';
      t.title = '';
    }
    N.showTab('');
    saveSession();
    update();
  }

  /** Address bar / search: open what was typed in the current tab. */
  function navigate(input, opts) {
    const url = C.resolveInput(input, settings.searchEngine);
    if (!url) return;
    if (!(opts && opts.keepScreen)) {
      closeScreen(true);
      closeSheet(true);
    }
    let t = activeTab();
    if (!t || (opts && opts.newTab)) {
      t = openTab(url);
      return;
    }
    if (t.home) {
      t.home = false;
      t.fromHome = !t.live;
      t.url = url;
      t.title = '';
      if (t.live) {
        N.loadUrl(t.id, url);
        N.showTab(t.id);
      } else {
        ensureLive(t, true);
      }
    } else if (t.live) {
      t.url = url;
      N.loadUrl(t.id, url);
    } else {
      t.url = url;
      ensureLive(t, true);
    }
    t.loading = true;
    t.progress = 5;
    saveSession();
    update();
  }

  function switchSpace(id) {
    if (!spaceById(id)) return;
    space = id;
    applySpaceColors();
    let t = tab(activeBySpace[id]);
    if (!t || t.space !== id) t = tabsIn(id).slice(-1)[0];
    if (t) activate(t.id);
    else openTab('', { space: id });
    update();
  }

  function goBack() {
    if (closeTopLayer()) return;
    const t = activeTab();
    if (!t) return N.minimize();
    if (t.home) {
      if (t.live && t.url) {
        t.home = false;
        ensureLive(t, true);
        update();
        return;
      }
      return N.minimize();
    }
    if (t.back) return N.nav(t.id, 'back');
    if (t.fromHome) return goHome(t, true);
    if (t.opener && tab(t.opener)) {
      const opener = t.opener;
      closeTab(t.id);
      activate(opener);
      update();
      return;
    }
    if (t.external) {
      closeTab(t.id);
      return N.minimize();
    }
    N.minimize();
  }

  function closeTopLayer() {
    if (sheet) {
      closeSheet();
      return true;
    }
    if (findOpen) {
      closeFind();
      update();
      return true;
    }
    if (screen && screen !== 'welcome') {
      closeScreen();
      return true;
    }
    return false;
  }

  function neighbourTab(dir) {
    const list = tabsIn(space);
    const i = list.findIndex((t) => t.id === activeId);
    if (i < 0) return null;
    return list[i + dir] || null;
  }

  // ------------------------------------------------------------------------------------------
