  function renderBar() {
    const t = activeTab();
    const label = $('#pill-label');
    const shieldBtn = $('#pill-shield');
    const count = $('#pill-count');
    label.className = '';
    label.textContent = '';
    shieldBtn.classList.remove('off', 'insecure');
    if (!t || t.home || !t.url) {
      label.textContent = 'Search or type URL';
      label.className = 'placeholder';
      count.hidden = true;
    } else {
      const real = C.realUrl(t.url) || t.url;
      const d = C.displayUrl(real);
      if (d.search) {
        label.append(el('span', { class: 'muted', text: '🔍 ' }), d.search);
      } else if (/^http:/i.test(real)) {
        label.append(el('span', { class: 'warn', text: 'Not secure ' }), d.text);
        shieldBtn.classList.add('insecure');
      } else {
        label.textContent = d.text || real;
      }
      if (!shieldOnFor(real)) shieldBtn.classList.add('off');
      count.hidden = !(t.blocked > 0) || !shieldOnFor(real);
      count.textContent = t.blocked > 99 ? '99+' : String(t.blocked);
    }
    const noPage = !t || t.home || !t.url;
    shieldBtn.classList.toggle('search', noPage);
    shieldBtn.firstElementChild.innerHTML = window.ICONS[noPage ? 'search' : shieldBtn.classList.contains('off') ? 'shieldOff' : 'shield'];
    const reload = $('#pill-reload');
    const loading = t && !t.home && t.loading;
    reload.innerHTML = window.ICONS[loading ? 'stop' : 'reload'];
    reload.style.visibility = t && !t.home && t.url ? 'visible' : 'hidden';
    $('#pill-focus').hidden = !focusActive();
    const n = tabsIn(space).length;
    const tc = $('#tab-count');
    tc.textContent = n > 99 ? ':D' : String(n);
    tc.classList.toggle('many', n > 9);
    if (tc.dataset.n && tc.dataset.n !== String(n) && !reducedMotion) {
      tc.classList.remove('bump');
      void tc.offsetWidth;
      tc.classList.add('bump');
    }
    tc.dataset.n = String(n);
    $('#b-tabs').classList.toggle('space-tinted', space !== settings.spaces[0].id);
    renderProgress();
  }

  function renderProgress() {
    const t = activeTab();
    const p = $('#progress');
    const on = !!(t && !t.home && t.loading);
    p.classList.toggle('on', on);
    p.firstElementChild.style.transform = 'scaleX(' + (on ? Math.max(8, t.progress || 0) : 100) / 100 + ')';
    syncNativeBar();
  }

  function setupBar() {
    $('#b-back').onclick = () => {
      haptic();
      goBack();
    };
    $('#pill-text').onclick = () => {
      if (pillSwiped) return;
      openSearch('', {});
    };
    $('#pill-shield').onclick = () => {
      if (pageTab()) openShieldSheet();
      else openSearch('', {});
    };
    $('#pill-reload').onclick = () => {
      const t = pageTab();
      if (!t) return;
      haptic();
      if (!t.live) ensureLive(t, true);
      else N.nav(t.id, t.loading ? 'stop' : 'reload');
    };
    $('#b-tabs').onclick = () => openTabsScreen();
    $('#b-tabs').addEventListener('contextmenu', (e) => {
      e.preventDefault();
      haptic();
      openTab('');
    });
    $('#b-menu').onclick = () => openMenu();
    $('#b-ai').onclick = () => {
      haptic();
      closeFind();
      ai.open();
    };

    // Swipe the address pill sideways to move between tabs.
    const pill = $('#pill');
    let sx = 0;
    let sy = 0;
    let dx = 0;
    let tracking = false;
    let pillSwiped = false;
    pill.addEventListener('touchstart', (e) => {
      sx = e.touches[0].clientX;
      sy = e.touches[0].clientY;
      dx = 0;
      tracking = true;
      pillSwiped = false;
    }, { passive: true });
    pill.addEventListener('touchmove', (e) => {
      if (!tracking) return;
      dx = e.touches[0].clientX - sx;
      const dy = e.touches[0].clientY - sy;
      if (Math.abs(dy) > Math.abs(dx) && !pillSwiped) return;
      if (Math.abs(dx) > 10) pillSwiped = true;
      if (pillSwiped) {
        const target = neighbourTab(dx < 0 ? 1 : -1);
        const damp = target ? 1 : 0.25;
        pill.style.transition = 'none';
        pill.style.transform = 'translateX(' + dx * damp + 'px)';
        pill.style.opacity = String(1 - Math.min(0.5, Math.abs(dx) / 400));
      }
    }, { passive: true });
    pill.addEventListener('touchend', () => {
      tracking = false;
      pill.style.transition = '';
      pill.style.transform = '';
      pill.style.opacity = '';
      if (pillSwiped && Math.abs(dx) > 70) swipeToTab(dx < 0 ? 1 : -1);
      setTimeout(() => {
        pillSwiped = false;
      }, 50);
    });
  }

  function swipeToTab(dir) {
    const target = neighbourTab(dir);
    if (!target) return;
    haptic('tick');
    activate(target.id, dir);
    update();
    // The address glides in from the side the new tab came from.
    const label = $('#pill-text');
    label.classList.remove('from-right', 'from-left');
    void label.offsetWidth;
    label.classList.add(dir > 0 ? 'from-right' : 'from-left');
    setTimeout(() => label.classList.remove('from-right', 'from-left'), 400);
  }

