  function renderClock() {
    const now = new Date();
    const h24 = now.getHours();
    const h = h24 % 12 || 12;
    const m = String(now.getMinutes()).padStart(2, '0');
    const clock = $('#clock');
    const text = h + ':' + m + (h24 < 12 ? 'am' : 'pm');
    if (clock.dataset.t !== text) {
      clock.dataset.t = text;
      clock.textContent = h + ':' + m;
      clock.append(el('small', { text: h24 < 12 ? 'am' : 'pm' }));
    }
    $('#greeting').textContent = C.greeting(h24) + (settings.name ? ', ' + settings.name : '');
    $('#date').textContent = now.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
  }

  function renderHome() {
    renderClock();
    const sp = spaceById(space) || settings.spaces[0];
    $('#space-chip-icon').textContent = sp.icon;
    $('#space-chip-name').textContent = sp.name;
    $('#foot-name').textContent = settings.name || 'you';
    renderWeather();
    renderFocusCard();
