  }

  function renderTiles() {
    const box = $('#tiles');
    const sig = JSON.stringify(bookmarks.slice(0, 11).map((b) => [b.url, b.title, !!faviconFor(b.url)]));
    if (box.dataset.sig === sig) return;
    box.dataset.sig = sig;
    box.textContent = '';
