      const tile = el('button', { class: 'tile', onclick: () => navigate(b.url) },
        siteIcon(b.url, b.title, 'tile-icon', true, true),
        el('span', { class: 'tile-label', text: b.title || C.hostOf(b.url) }));
      tile.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        haptic();
        openFavoriteSheet(b);
      });
      box.append(tile);
    });
    box.append(el('button', { class: 'tile', onclick: () => openSearch('', {}) }, el('span', { class: 'tile-icon add' }, icon('plus')), el('span', { class: 'tile-label', text: 'Add' })));
  }

  function renderWeather() {
    const unit = settings.tempUnit === 'F' ? '°F' : '°';
    const conv = (c) => Math.round(settings.tempUnit === 'F' ? C.toF(c) : c);
    const w = weather && weather.weather;
    const cityName = settings.city ? settings.city.name : '';
    if (w) {
      const info = C.weatherInfo(w.code, w.isDay);
      $('#wx-emoji').textContent = info.emoji;
      $('#wx-temp').textContent = conv(w.temp) + unit;
      $('#wx-desc').textContent = info.label + ' · ' + cityName;
      const parts = [];
      if (w.max != null) parts.push('H ' + conv(w.max) + '° L ' + conv(w.min) + '°');
      if (w.rain != null) parts.push('💧' + w.rain + '%');
      $('#wx-more').textContent = parts.join(' · ');
    } else {
      $('#wx-desc').textContent = weather === false ? 'Weather unavailable' : 'Loading…';
      $('#wx-more').textContent = cityName;
    }
    const a = weather && weather.air;
    if (a) {
      const lvl = C.aqiLevel(a.aqi);
      $('#aq-num').textContent = Math.round(a.aqi);
      const badge = $('#aq-badge');
      badge.textContent = lvl.label;
      badge.style.background = lvl.color;
      $('#aq-pm').textContent = 'PM2.5 ' + (a.pm25 != null ? Math.round(a.pm25) : '–') + ' · ' + cityName;
      $('#aq-tip').textContent = lvl.tip;
    } else {
      $('#aq-badge').textContent = weather === false ? 'Offline' : '…';
      $('#aq-badge').style.background = '';
      $('#aq-pm').textContent = cityName;
      $('#aq-tip').textContent = '';
    }
  }

  let weatherLoading = false;

  async function refreshWeather(force) {
    const city = settings.city;
    if (!city || weatherLoading) return;
    const key = city.lat + ',' + city.lon;
    if (!force && weather && weather.key === key && Date.now() - weather.at < 15 * 60000) return;
    weatherLoading = true;
    const [wb, ab] = await Promise.all([nativeFetch(C.weatherUrl(city)), nativeFetch(C.airUrl(city))]);
    weatherLoading = false;
    const w = wb && C.parseWeather(wb);
    const a = ab && C.parseAir(ab);
    if (w || a) {
      weather = { key, at: Date.now(), weather: w, air: a };
      saveSoon('weather', () => weather, 100);
    } else if (!weather || weather.key !== key) {
      weather = false;
    }
    if (!$('#home').hidden) renderWeather();
  }

  function renderFocusCard() {
    const btn = $('#focus-btn');
    const prog = $('#focus-progress');
    if (focusActive()) {
      const left = settings.focusEndsAt - Date.now();
      const total = Math.max(1, settings.focusEndsAt - settings.focusStartedAt);
      $('#focus-line').textContent = '';
      $('#focus-line').append(el('div', { class: 'focus-big', text: C.clockText(left) + ' left' }), el('div', { class: 'dim', text: 'Distracting sites are paused' }));
      btn.textContent = 'End';
      btn.className = 'btn ghost';
      prog.hidden = false;
      $('#focus-bar').style.width = Math.min(100, (100 * (total - left)) / total) + '%';
    } else {
      const streak = C.focusStreak(stats.focus);
      $('#focus-line').textContent = '';
      $('#focus-line').append(el('b', { text: C.minutesText(C.sumLastDays(stats.focus, 1)) }), el('span', { class: 'dim', text: ' focused today' }));
      if (streak >= 2) $('#focus-line').append(el('div', { class: 'streak', text: '🔥 ' + streak + '-day streak' }));
      btn.textContent = 'Start ' + settings.focusMinutes + ' min';
      btn.className = 'btn';
      prog.hidden = true;
    }
  }

