  // ------------------------------------------------------------------------------------------
  // Search
  // ------------------------------------------------------------------------------------------

  let suggestSeq = 0;
  let remoteSuggestions = [];
  let suggestTimer = null;
  let completion = '';
  let selectedSuggestion = null;

  function openSearch(initial, opts) {
    opts = opts || {};
    const wasSearch = screen === 'search';
    screen = 'search';
    closeSheet(true);
    const q = $('#q');
    q.value = initial || '';
    remoteSuggestions = [];
    completion = '';
    const t = pageTab();
    const cp = $('#current-page');
    if (t && opts.current !== false) {
      cp.hidden = false;
      const real = C.realUrl(t.url) || t.url;
      $('#cp-title').textContent = t.title || C.hostOf(real);
      $('#cp-url').textContent = real;
      const data = faviconFor(real);
      $('#cp-icon').src = data || 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#8884"/></svg>');
    } else {
      cp.hidden = true;
    }
    update();
    if (!wasSearch) animateIn($('#search'));
    q.focus();
    renderSuggestions();
    setTimeout(() => q.focus(), 60);
  }

  function historyIndex() {
    const map = new Map();
    for (const h of history) {
      const e = map.get(h.url);
      if (e) e.visits++;
      else map.set(h.url, { url: h.url, title: h.title, ts: h.ts, visits: 1 });
    }
    for (const b of bookmarks) {
      const e = map.get(b.url);
      if (e) e.fav = true;
      else map.set(b.url, { url: b.url, title: b.title, ts: 0, visits: 1, fav: true });
    }
    return Array.from(map.values());
  }

  let indexCache = null;
  let indexCacheAt = 0;

  function entriesIndex() {
    if (!indexCache || Date.now() - indexCacheAt > 5000) {
      indexCache = historyIndex();
      indexCacheAt = Date.now();
    }
    return indexCache;
  }

  function boldMatch(text, query) {
    const span = el('span');
    const i = query ? text.toLowerCase().indexOf(query.toLowerCase()) : -1;
    if (i < 0) span.textContent = text;
    else span.append(text.slice(0, i), el('b', { text: text.slice(i, i + query.length) }), text.slice(i + query.length));
    return span;
  }

  function suggestionRow(opts) {
    const row = el('div', { class: 'sugg', role: 'option', onclick: opts.action },
      opts.iconEl || el('span', { class: 'sugg-icon' }, icon(opts.icon || 'search')),
      el('div', { class: 'sugg-text' }, el('div', { class: 'sugg-title' }, opts.titleEl || opts.title), opts.sub ? el('div', { class: 'sugg-url' + (opts.subClass ? ' ' + opts.subClass : ''), text: opts.sub }) : null),
      opts.fill ? el('button', { class: 'icon-btn sugg-fill', 'aria-label': 'Use this', onclick: (e) => { e.stopPropagation(); fillQuery(opts.fill); } }, icon('fill')) : null);
    return row;
  }

  function fillQuery(text) {
    const q = $('#q');
    q.value = text + ' ';
    q.focus();
    onQueryInput({ inputType: 'insertText' });
  }

  function renderSuggestions() {
    const box = $('#suggestions');
    box.textContent = '';
    const text = $('#q').value.trim();
    const lower = text.toLowerCase();
    $('#q-clear').hidden = !text;
    $('#q-mic').hidden = !!text || !device().voice;
    $('#current-page').hidden = !!text || !pageTab();
    if (!text) {
      // Recent sites, newest nearest the keyboard.
      const seen = new Set();
      const recent = [];
      for (const h of history) {
        const host = C.hostOf(h.url);
        if (!host || seen.has(h.url)) continue;
        seen.add(h.url);
        recent.push(h);
        if (recent.length >= 8) break;
      }
      recent.forEach((h) => {
        box.append(suggestionRow({ iconEl: siteIcon(h.url, h.title, 'sugg-icon'), title: h.title || C.hostOf(h.url), sub: C.hostOf(h.url), action: () => navigate(h.url) }));
      });
      if (recent.length) box.append(el('div', { class: 'sugg-head', text: 'Recent' }));
      return;
    }
    const isUrl = C.looksLikeUrl(text);
    const target = completion && completion.toLowerCase().indexOf(lower) === 0 ? completion : text;
    // A sum gets its answer right away (rows are listed bottom-up, nearest the keyboard first).
    const answer = isUrl ? null : C.calc(text);
    if (answer !== null) {
      const shown = C.fmtNumber(answer);
      box.append(suggestionRow({ iconEl: el('span', { class: 'sugg-icon calc' }, icon('calc')), titleEl: el('span', { class: 'calc-answer', text: '= ' + shown }), sub: text + ' · tap to copy', action: () => { N.copy(String(answer)); haptic('confirm'); toast('Copied ' + shown); } }));
    }
    box.append(suggestionRow(isUrl || completion
      ? { icon: 'globe', title: target, sub: 'Open site', action: () => navigate(target) }
      : { icon: 'search', title: text, sub: 'Search ' + C.engine(settings.searchEngine).name, action: () => navigate(text) }));
    if (!isUrl && completion) box.append(suggestionRow({ icon: 'search', title: text, sub: 'Search ' + C.engine(settings.searchEngine).name, action: () => navigate(text) }));
    if (!isUrl && answer === null && (/\s\S/.test(text) || /\?$/.test(text)) && text.length >= 6 && ai) {
      box.append(suggestionRow({ iconEl: el('span', { class: 'sugg-icon ai', text: '✦' }), title: 'Ask TP AI', sub: text, action: () => { $('#q').blur(); closeScreen(true); ai.open(text); } }));
    }

    const tabMatches = tabs.filter((t) => !t.home && !t.hidden && t.id !== activeId && ((t.title || '').toLowerCase().indexOf(lower) >= 0 || C.hostOf(t.url).indexOf(lower) >= 0)).slice(0, 2);
    tabMatches.forEach((t) => {
      box.append(suggestionRow({ iconEl: siteIcon(t.url, t.title, 'sugg-icon'), titleEl: boldMatch(t.title || C.hostOf(t.url), text), sub: 'Switch to tab · ' + (spaceById(t.space) || {}).name, subClass: 'tab', action: () => { closeScreen(true); activate(t.id); update(); } }));
    });

    const ranked = C.rankEntries(entriesIndex(), text, 4);
    ranked.forEach((e) => {
      box.append(suggestionRow({ iconEl: siteIcon(e.url, e.title, 'sugg-icon'), titleEl: boldMatch(e.title || C.hostOf(e.url), text), sub: (e.fav ? '★ ' : '') + (C.realUrl(e.url) || '').replace(/^https?:\/\/(www\.)?/, ''), action: () => navigate(e.url) }));
    });

    remoteSuggestions.filter((s) => s.toLowerCase() !== lower).slice(0, 5).forEach((s) => {
      box.append(suggestionRow({ icon: 'search', titleEl: boldMatch(s, text), action: () => navigate(s), fill: s }));
    });
  }

  function renderGhost() {
    const q = $('#q');
    const ghost = $('#q-ghost');
    ghost.textContent = '';
    if (!completion || !q.value || document.activeElement !== q) return;
    const typed = q.value;
    if (completion.toLowerCase().indexOf(typed.toLowerCase()) !== 0) return;
    ghost.append(el('i', { text: typed }), el('em', { text: completion.slice(typed.length) }));
  }

  function onQueryInput(e) {
    const text = $('#q').value;
    const deleting = e && e.inputType && e.inputType.indexOf('delete') === 0;
    completion = deleting ? '' : C.inlineCompletion(C.rankEntries(entriesIndex(), text.trim(), 10), text.trim());
    renderGhost();
    renderSuggestions();
    clearTimeout(suggestTimer);
    const trimmed = text.trim();
    if (!settings.suggestions || !trimmed || C.looksLikeUrl(trimmed)) {
      remoteSuggestions = [];
      return;
    }
    const seq = ++suggestSeq;
    suggestTimer = setTimeout(async () => {
      const body = await nativeFetch(C.suggestUrl(trimmed, settings.searchEngine), 5000);
      if (seq !== suggestSeq || screen !== 'search') return;
      remoteSuggestions = body ? C.parseSuggest(body) : [];
      renderSuggestions();
    }, 140);
  }

  function setupSearch() {
    const q = $('#q');
    q.addEventListener('input', onQueryInput);
    $('#search-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const text = q.value.trim();
      if (!text) return;
      const go = completion && completion.toLowerCase().indexOf(text.toLowerCase()) === 0 ? completion : text;
      q.blur();
      navigate(go);
    });
    $('#search-close').onclick = () => closeScreen();
    $('#q-clear').onclick = () => {
      q.value = '';
      completion = '';
      renderGhost();
      renderSuggestions();
      q.focus();
    };
    $('#cp-copy').onclick = () => {
      const t = pageTab();
      if (!t) return;
      N.copy(C.realUrl(t.url) || t.url);
      toast('Link copied');
    };
    $('#cp-share').onclick = () => {
      const t = pageTab();
      if (t) N.share(C.realUrl(t.url) || t.url, t.title || '');
    };
    $('#cp-qr').onclick = () => {
      const t = pageTab();
      if (!t) return;
      q.blur();
      openQrSheet(t);
    };
    $('#q-mic').onclick = () => {
      haptic();
      q.blur();
      N.voice('search', settings.voiceLang || '');
    };
    $('#cp-edit').onclick = () => {
      const t = pageTab();
      if (!t) return;
      q.value = C.realUrl(t.url) || t.url;
      completion = '';
      renderSuggestions();
      q.focus();
      q.select();
    };
  }

  // ------------------------------------------------------------------------------------------
  // Screens
  // ------------------------------------------------------------------------------------------

  function openScreen(id, focusSection) {
    closeSheet(true);
    closeFind();
    const wasOpen = screen;
    screen = id;
    if (id === 'history') renderHistory();
    if (id === 'settings') renderSettings(focusSection);
    if (id === 'favorites') renderFavorites();
    update();
    const elScreen = $('#' + id);
    if (elScreen && !focusSection) elScreen.scrollTop = 0;
    if (wasOpen !== id) animateIn(elScreen);
  }

  function closeScreen(silent) {
    if (!screen) return;
    if (screen === 'search') $('#q').blur();
    if (screen === 'ai') $('#ai-q').blur();
    if (screen === 'reader') closeReader();
    const id = screen;
    screen = null;
    if (silent) return;
    closingScreen = id;
    animateOut($('#' + id), () => {
      if (closingScreen === id) closingScreen = null;
      update();
    });
    update();
  }

  // ------------------------------------------------------------------------------------------
  // Tab switcher
  // ------------------------------------------------------------------------------------------

  let tabsRenderQueued = false;

  function openTabsScreen() {
    const t = activeTab();
    if (t && t.live && !t.home) N.thumbnail(t.id);
    tabsViewSpace = space;
    const wasOpen = screen === 'tabs';
    screen = 'tabs';
    closeSheet(true);
    closeFind();
    update();
    const active = $('.tab-card.active');
    if (active) active.scrollIntoView({ block: 'center' });
    if (!wasOpen) animateIn($('#tabs'));
  }

  function queueRenderTabs() {
    if (tabsRenderQueued) return;
    tabsRenderQueued = true;
    requestAnimationFrame(() => {
      tabsRenderQueued = false;
      if (screen === 'tabs') renderTabs();
    });
  }

  function renderTabs() {
    const chips = $('#space-chips');
    chips.textContent = '';
    settings.spaces.forEach((sp) => {
      const colors = C.SPACE_COLORS[sp.color] || C.SPACE_COLORS.violet;
      chips.append(el('button', {
        class: 'space-chip' + (sp.id === tabsViewSpace ? ' on' : ''),
        style: '--sc1:' + colors[0] + ';--sc2:' + colors[1],
        onclick: () => {
          tabsViewSpace = sp.id;
          haptic();
          renderTabs();
        },
      }, el('span', { text: sp.icon }), el('span', { text: sp.name }), el('span', { class: 'count', text: String(tabsIn(sp.id).length) })));
    });
    chips.append(el('button', { class: 'space-chip add', onclick: () => openSpaceEditor(null) }, icon('plus')));

    const grid = $('#tab-grid');
    grid.textContent = '';
    const list = tabsIn(tabsViewSpace);
    $('#tabs-empty').hidden = list.length > 0;
    list.forEach((t, i) => grid.append(tabCard(t, i)));
  }

  function tabCard(t, index) {
    const real = C.realUrl(t.url) || t.url;
    const title = t.home ? 'New tab' : t.title || C.hostOf(real) || real;
    const thumb = el('div', { class: 'tab-thumb' });
    if (t.home) {
      thumb.append(el('div', { class: 'home-ph' }, el('div', { class: 'logo', text: 'TP' }), 'New tab'));
    } else if (t.thumb) {
      thumb.style.backgroundImage = 'url("' + t.thumb + '")';
    } else {
      const ph = siteIcon(real, title, 'ph');
      if (!ph.classList.contains('letter')) ph.style.background = 'var(--card)';
      thumb.append(ph);
    }
    const head = el('div', { class: 'tab-head' },
      t.home ? el('span', { class: 'mini-letter logo', text: 'TP' }) : siteIcon(real, title, 'mini-letter'),
      el('div', { class: 'tab-title', text: title }),
      el('button', { class: 'icon-btn tab-close', 'aria-label': 'Close tab', onclick: (e) => { e.stopPropagation(); closeTabAnimated(card, t.id); } }, icon('close')));
    const card = el('div', { class: 'tab-card' + (t.id === activeId ? ' active' : '') }, head, thumb);
    card.style.setProperty('--i', String(Math.min(index || 0, 12)));
    card.onclick = () => {
      if (card.dataset.swiped || card.classList.contains('opening')) return;
      haptic();
      card.classList.add('opening');
      setTimeout(() => {
        closeScreen(true);
        activate(t.id);
        update();
      }, reducedMotion ? 0 : 160);
    };
    // Swipe a card sideways to close it.
    let sx = 0;
    let sy = 0;
    let dx = 0;
    let horizontal = null;
    card.addEventListener('touchstart', (e) => {
      sx = e.touches[0].clientX;
      sy = e.touches[0].clientY;
      dx = 0;
      horizontal = null;
      delete card.dataset.swiped;
    }, { passive: true });
    card.addEventListener('touchmove', (e) => {
      dx = e.touches[0].clientX - sx;
      const dy = e.touches[0].clientY - sy;
      if (horizontal === null && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) horizontal = Math.abs(dx) > Math.abs(dy);
      if (!horizontal) return;
      card.dataset.swiped = '1';
      card.style.transition = 'none';
      card.style.transform = 'translateX(' + dx + 'px) rotate(' + dx / 40 + 'deg)';
      card.style.opacity = String(1 - Math.min(0.8, Math.abs(dx) / 250));
    }, { passive: true });
    card.addEventListener('touchend', () => {
      card.style.transition = '';
      if (horizontal && Math.abs(dx) > 90) {
        closeTabAnimated(card, t.id, dx);
      } else {
        card.style.transform = '';
        card.style.opacity = '';
      }
      setTimeout(() => delete card.dataset.swiped, 60);
    });
    return card;
  }

  function closeTabAnimated(card, id, dx) {
    haptic();
    card.style.transform = 'translateX(' + (dx && dx < 0 ? -110 : 110) + '%)';
    card.style.opacity = '0';
    setTimeout(() => {
      const wasActive = id === activeId;
      closeTab(id);
      if (wasActive && screen === 'tabs') {
        tabsViewSpace = space;
      }
      if (screen === 'tabs') renderTabs();
    }, 170);
  }

  function setupTabs() {
    $('#tabs-new').onclick = () => {
      haptic();
      closeScreen(true);
      openTab('', { space: tabsViewSpace });
    };
    $('#tabs-done').onclick = () => {
      if (tabsViewSpace !== space) switchSpace(tabsViewSpace);
      closeScreen();
    };
    $('#tabs-closeall').onclick = () => {
      const sp = spaceById(tabsViewSpace);
      const list = tabsIn(tabsViewSpace);
      if (!list.length) return;
      openSheet('confirm', (s) => {
        s.append(
          el('div', { class: 'sheet-hero' }, el('h3', { text: 'Close all ' + list.length + ' tabs in ' + sp.name + '?' }), el('p', { text: 'You can find them again in History.' })),
          el('div', { class: 'sheet-actions' },
            el('button', { class: 'btn ghost', text: 'Cancel', onclick: () => closeSheet() }),
            el('button', { class: 'btn', text: 'Close all', onclick: () => {
              closeSheet(true);
              list.forEach((t) => closeTab(t.id));
              closeScreen(true);
              update();
            } })));
      });
    };
  }

  // ------------------------------------------------------------------------------------------
  // Sheets
  // ------------------------------------------------------------------------------------------

  function openSheet(kind, build) {
    const wasOpen = !!sheet && !$('#sheet').classList.contains('anim-out');
    sheet = kind;
    const s = $('#sheet');
    const b = $('#backdrop');
    const oldH = wasOpen ? s.offsetHeight : 0;
    s.textContent = '';
    s.className = 'sheet sheet-' + kind;
    s.style.transition = s.style.transform = b.style.transition = b.style.opacity = '';
    build(s);
    window.fillIcons(s);
    s.hidden = false;
    b.hidden = false;
    s.scrollTop = 0;
    update();
    // Items follow the sheet up one after another.
    Array.from(s.children).forEach((c, i) => c.style.setProperty('--i', String(Math.min(i, 10))));
    if (!wasOpen) {
      animateIn(s);
      animateIn(b);
    } else if (!reducedMotion) {
      // One sheet turning into another (menu → Translate): the height glides and the new items fade up.
      const newH = s.offsetHeight;
      if (Math.abs(newH - oldH) > 4 && s.animate) {
        s.animate([{ height: oldH + 'px' }, { height: newH + 'px' }], { duration: 420, easing: 'cubic-bezier(0.2, 0.9, 0.25, 1)' });
      }
      s.classList.add('sheet-swap');
      setTimeout(() => s.classList.remove('sheet-swap'), 700);
    }
  }

  function closeSheet(silent) {
    if (!sheet) return;
    sheet = null;
    const s = $('#sheet');
    const b = $('#backdrop');
    if (silent) {
      s.hidden = true;
      b.hidden = true;
      return;
    }
    animateOut(b, () => {
      if (!sheet) b.hidden = true;
      update();
    });
    animateOut(s, () => {
      if (!sheet) s.hidden = true;
      update();
    });
  }

  function sheetItem(iconName, text, action, opts) {
