        el('button', { disabled: !t, onclick: () => { closeSheet(true); openFind(); } }, icon('find'), 'Find'),
        el('button', { onclick: () => { closeSheet(); N.openDownloads(); } }, icon('download'), 'Downloads'),
        el('button', { disabled: !t, onclick: () => openReader(false) }, icon('reader'), 'Reader'),
        el('button', { disabled: !t, onclick: () => openReader(true) }, icon('speaker'), 'Listen'),
        el('button', { disabled: !t, onclick: () => openTranslateSheet(t) }, icon('translate'), 'Translate'),
        el('button', { disabled: !t, onclick: () => { closeSheet(); takeScreenshot(t); } }, icon('screenshot'), 'Screenshot'),
        el('button', { disabled: !t, onclick: () => openQrSheet(t) }, icon('qr'), 'QR code'));
      s.append(quick);
