      s.append(sheetItem('history', 'History', () => openScreen('history')));
      if (closedTabs.length) {
        s.append(sheetItem('bgtab', 'Reopen closed tab', () => {
          const c = closedTabs.pop();
          closeSheet(true);
          openTab(c.url, { space: spaceById(c.space) ? c.space : space });
