        sub: focusActive() ? C.clockText(settings.focusEndsAt - Date.now()) + ' left' : 'Pause distracting sites for a while',
      }));
      if (t) {
        const on = shieldOnFor(real);
        s.append(sheetItem(on ? 'shield' : 'shieldOff', 'TP Shield on this site', () => { toggleSiteShield(t); closeSheet(); }, {
          sub: !settings.shield ? 'Turned off in Settings' : on ? t.blocked + ' blocked on this page' : 'Ads and trackers allowed on ' + C.hostOf(real),
          right: switchEl(on),
