        s.append(sheetItem('warn', 'Page not working?', () => openProblemSheet(), { sub: 'Fixes to try, and a report you can send' }));
      }
      s.append(sheetItem('settings', 'Settings', () => openScreen('settings')));
      if (!isDefaultBrowser && canDefault()) s.append(sheetItem('check', 'Make TP your default browser', () => { closeSheet(); N.makeDefault(); }, { accent: true }));
    });
  }

  function toggleBookmark(t) {
    const real = C.realUrl(t.url) || t.url;
    const i = bookmarks.findIndex((b) => b.url === real);
    if (i >= 0) {
      bookmarks.splice(i, 1);
      toast('Removed from Favorites');
    } else {
      bookmarks.unshift({ url: real, title: t.title || C.hostOf(real) });
      toast('Added to Favorites ⭐');
    }
    indexCache = null;
    saveBookmarks();
  }

  function toggleSiteShield(t) {
    const real = C.realUrl(t.url) || t.url;
    const root = C.rootDomain(C.hostOf(real));
    if (!root) return;
    if (!settings.shield) {
      settings.shield = true;
      settings.shieldAllow = settings.shieldAllow.filter((d) => !C.hostInList(root, [d]));
    } else if (shieldOnFor(real)) {
      settings.shieldAllow = settings.shieldAllow.concat([root]);
      toast('TP Shield off for ' + root);
    } else {
      settings.shieldAllow = settings.shieldAllow.filter((d) => !C.hostInList(C.hostOf(real), [d]));
      toast('TP Shield on for ' + root);
    }
    saveSettings();
    pushShield();
    if (t.live) N.nav(t.id, 'reload');
  }

