  // ------------------------------------------------------------------------------------------
  // Read aloud: Android's voice reads a list of pieces; "tts" events say which piece it's on
  // ------------------------------------------------------------------------------------------

  const speech = { seq: 0, items: [], index: -1, queued: 0, playing: false, owner: '', warned: {} };
  const speechListeners = [];
  const SPEECH_AHEAD = 20;

  function speechEmit() {
    speechListeners.forEach((fn) => {
      try {
        fn(speech);
      } catch (e) {
        // a listener failing shouldn't stop the others
      }
    });
  }

  function speechTopUp(first) {
    const end = Math.min(speech.items.length, Math.max(speech.index, 0) + SPEECH_AHEAD);
    while (speech.queued < end) {
      const i = speech.queued;
      const item = speech.items[i];
      N.speak('s' + speech.seq + '-' + i, item.text, item.lang || '', settings.speechRate || 1, !(first && i === speech.index));
      speech.queued++;
    }
  }

  function speechFrom(index) {
    speech.seq++;
    speech.index = index;
    speech.queued = index;
    speech.playing = true;
    speechTopUp(true);
    speechEmit();
  }

  /** items: [{ text, lang, ref }]. opts.owner names who is speaking ("reader", "ai:<id>"). */
  function speak(items, opts) {
    opts = opts || {};
    speech.items = (items || []).filter((x) => x && x.text && String(x.text).trim());
    speech.owner = opts.owner || '';
    if (!speech.items.length) return stopSpeech();
    speechFrom(Math.max(0, Math.min(opts.start || 0, speech.items.length - 1)));
  }

  function pauseSpeech() {
    if (!speech.playing) return;
    N.stopSpeaking();
    speech.seq++;
    speech.playing = false;
    speechEmit();
  }

  function resumeSpeech() {
    if (speech.items.length) speechFrom(Math.max(0, speech.index));
  }

  function stopSpeech() {
    if (speech.playing) N.stopSpeaking();
    speech.seq++;
    speech.playing = false;
    speech.items = [];
    speech.index = -1;
    speech.owner = '';
    speechEmit();
  }

  function onTts(e) {
    if (e.state === 'unavailable') {
      if (!speech.warned.unavailable) toast(IOS ? 'Read aloud isn’t available right now' : 'Read aloud isn’t available on this phone. Install “Speech Services by Google” from the Play Store');
      speech.warned.unavailable = true;
      stopSpeech();
      return;
    }
    if (e.state === 'nolang') {
      toast(IOS ? 'Add a voice for this language: Settings → Accessibility → Spoken Content → Voices' : 'This phone has no voice for this language yet. Add one in Android Settings → Text-to-speech');
      return;
    }
    const m = /^s(\d+)-(\d+)$/.exec(e.id || '');
    if (!m || Number(m[1]) !== speech.seq) return;
    const i = Number(m[2]);
    if (e.state === 'start') {
      speech.index = i;
      speech.playing = true;
      speechTopUp(false);
      speechEmit();
    } else if ((e.state === 'done' || e.state === 'error') && i >= speech.items.length - 1) {
      speech.playing = false;
      speech.seq++;
      speech.index = -1;
      const owner = speech.owner;
      speech.items = [];
      speech.owner = '';
      speech.finished = owner;
      speechEmit();
      speech.finished = '';
    }
  }

  /** Reads a TP AI answer (or any text) aloud; calling again with the same owner stops it. */
  function speakText(owner, text, lang) {
    if (speech.owner === owner && speech.playing) return stopSpeech();
    const parts = [];
    String(text || '').split(/\n+/).forEach((line) => C.splitSpeech(line, 1000).forEach((p) => parts.push({ text: p, lang: lang || C.speechLang(p, '') })));
    speak(parts, { owner });
  }

  // ------------------------------------------------------------------------------------------
  // Reader view: just the article, in comfortable text, and it can read itself aloud
  // ------------------------------------------------------------------------------------------

  let reader = null;

  function readerTheme() {
    const th = settings.reader.theme;
    return th === 'auto' || !READER_THEMES[th] ? (dark ? 'dark' : 'light') : th;
  }

  function readerBg() {
    return READER_THEMES[readerTheme()];
  }

  function applyReaderLook() {
    const r = $('#reader');
    ['light', 'sepia', 'dark'].forEach((th) => r.classList.toggle('rt-' + th, readerTheme() === th));
    r.classList.toggle('rf-sans', settings.reader.font === 'sans');
    r.style.setProperty('--rs', settings.reader.size + 'px');
  }

  function openReader(listen) {
    const t = pageTab();
    if (!t) return;
    closeSheet(true);
    closeFind();
    const wasOpen = screen === 'reader';
    screen = 'reader';
    reader = { tabId: t.id, data: null, items: [], listen: !!listen };
    applyReaderLook();
    const body = $('#reader-body');
    body.textContent = '';
    body.append(el('div', { class: 'r-skeleton' }, el('i', { class: 'w60' }), el('i', { class: 'w90 tall' }), el('i', { class: 'w40' }), el('i'), el('i'), el('i', { class: 'w80' }), el('i'), el('i', { class: 'w70' })));
    $('#reader-site').textContent = C.hostOf(t.url);
    $('#reader').classList.remove('hide-top');
    $('#reader').scrollTop = 0;
    renderReaderProgress();
    update();
    if (!wasOpen) animateIn($('#reader'));
    loadReader(t, listen);
  }

  async function loadReader(t, listen) {
    if (!t.live) {
      ensureLive(t, false);
      await waitForLoad(t.id, 15000);
    } else if (t.loading) {
      await waitForLoad(t.id, 8000);
    }
    const r = await evalInTab(t.id, window.TPReader.script(), 9000);
    if (!reader || reader.tabId !== t.id || screen !== 'reader') return;
    let d = null;
    try {
      d = JSON.parse(JSON.parse(r.result || '""') || 'null');
    } catch (e) {
      d = null;
    }
    if (!d || d.error || !Array.isArray(d.blocks) || !d.blocks.some((b) => b.x)) {
      renderReaderError(t);
      return;
    }
    reader.data = d;
    renderReader(d);
    if (listen) startReaderListen(0);
  }

  function renderReaderError(t) {
    const body = $('#reader-body');
    body.textContent = '';
    body.append(el('div', { class: 'r-empty' },
      el('div', { class: 'hero-icon', style: 'background:var(--r-soft);margin:0 auto 14px' }, icon('reader')),
      el('h2', { text: 'No article here' }),
      el('p', { text: 'Reader view works best on news, blogs, wikis and stories. This page doesn’t have much text to show.' }),
      el('button', { class: 'btn', text: 'Back to the page', onclick: () => closeScreen() })));
    window.fillIcons(body);
  }

  function renderReader(d) {
    const body = $('#reader-body');
    body.textContent = '';
    body.dir = d.dir === 'rtl' ? 'rtl' : 'ltr';
    const words = d.blocks.filter((b) => b.x).map((b) => b.x).join(' ');
    $('#reader-site').textContent = d.site || C.hostOf(d.url);
    const head = el('header', { class: 'r-head' },
      el('div', { class: 'r-kicker', text: d.site || C.hostOf(d.url) }),
      el('h1', { class: 'r-title', text: d.title || '' }),
      el('div', { class: 'r-meta' }, [d.byline, C.readingMinutes(words) + ' min read'].filter(Boolean).join(' · ')));
    body.append(head);
    reader.items = [];
    const titleLang = C.speechLang(d.title || words.slice(0, 400), d.lang);
    if (d.title) reader.items.push({ text: d.title, lang: titleLang, ref: head.querySelector('.r-title') });
    let list = null;
    let n = 0;
    d.blocks.forEach((b) => {
      let node = null;
      if (b.t === 'li') {
        const tag = b.o ? 'OL' : 'UL';
        if (!list || list.tagName !== tag) {
          list = el(tag.toLowerCase(), { class: 'r-list' });
          body.append(list);
        }
        node = el('li', { text: b.x });
        list.append(node);
      } else {
        list = null;
        if (b.t === 'h') node = el(b.l <= 2 ? 'h2' : 'h3', { class: 'r-h', text: b.x });
        else if (b.t === 'p') node = el('p', { text: b.x });
        else if (b.t === 'q') node = el('blockquote', { text: b.x });
        else if (b.t === 'pre') node = el('pre', { text: b.x });
        else if (b.t === 'cap') node = el('figcaption', { class: 'r-cap', text: b.x });
        else if (b.t === 'img') {
          const im = el('img', { src: b.src, alt: b.alt || '', loading: 'lazy', decoding: 'async', referrerpolicy: 'no-referrer' });
          node = el('figure', { class: 'r-fig' }, im);
          im.addEventListener('error', () => node.remove());
          im.addEventListener('load', () => node.classList.add('loaded'));
        }
        if (node) body.append(node);
      }
      if (!node) return;
      if (n < 12) node.style.setProperty('--d', String(n));
      n++;
      if (b.x && b.t !== 'cap' && b.t !== 'pre') {
        C.splitSpeech(b.x, 1200).forEach((piece) => reader.items.push({ text: piece, lang: C.speechLang(piece, d.lang), ref: node }));
      }
    });
    body.append(el('div', { class: 'r-end' },
      el('div', { class: 'r-end-mark', text: '✦' }),
      el('button', { class: 'btn ghost', text: 'Back to the full page', onclick: () => closeScreen() })));
    if (!reducedMotion) {
      body.classList.add('r-enter');
      setTimeout(() => body.classList.remove('r-enter'), 1100);
    }
    renderReaderProgress();
    updateReaderPlayer();
  }

  function startReaderListen(fromItem) {
    if (!reader || !reader.items.length) return;
    speak(reader.items, { owner: 'reader', start: fromItem || 0 });
  }

  function closeReader() {
    if (speech.owner === 'reader') stopSpeech();
    reader = null;
  }

  function renderReaderProgress() {
    const r = $('#reader');
    const max = r.scrollHeight - r.clientHeight;
    $('#reader-progress').style.transform = 'scaleX(' + (max > 0 ? Math.min(1, r.scrollTop / max) : 0) + ')';
  }

  let readerUserScrollAt = 0;

  function updateReaderPlayer() {
    const mine = speech.owner === 'reader' && reader;
    const player = $('#reader-player');
    const show = !!mine && (speech.playing || speech.index >= 0);
    if (show && player.hidden) {
      player.hidden = false;
      if (!reducedMotion) {
        player.classList.remove('in');
        void player.offsetWidth;
        player.classList.add('in');
      }
    } else if (!show && !player.hidden) {
      player.hidden = true;
    }
    $('#reader').classList.toggle('listening', show);
    player.classList.toggle('playing', !!(mine && speech.playing));
    $('#reader-listen').innerHTML = window.ICONS[mine && speech.playing ? 'pause' : 'speaker'];
    $$('#reader-body .speaking').forEach((x) => x.classList.remove('speaking'));
    if (!show) return;
    $('#rp-play').innerHTML = window.ICONS[speech.playing ? 'pause' : 'play'];
    $('#rp-rate').textContent = String(settings.speechRate || 1).replace(/^0\./, '.') + '×';
    const item = speech.items[speech.index];
    $('#rp-progress').style.transform = 'scaleX(' + (speech.items.length ? (speech.index + 1) / speech.items.length : 0) + ')';
    $('#rp-title').textContent = speech.playing ? 'Listening' : 'Paused';
    if (item && item.ref) {
      item.ref.classList.add('speaking');
      // Follow along, unless you've just scrolled somewhere yourself.
      if (speech.playing && Date.now() - readerUserScrollAt > 4000) {
        const rect = item.ref.getBoundingClientRect();
        if (rect.top < 90 || rect.bottom > window.innerHeight - 130) item.ref.scrollIntoView({ block: 'center', behavior: reducedMotion ? 'auto' : 'smooth' });
      }
    }
  }

  function readerJump(dir) {
    if (!speech.items.length) return;
    const cur = speech.items[Math.max(0, speech.index)];
    let i = Math.max(0, speech.index);
    if (dir > 0) {
      while (i < speech.items.length && speech.items[i].ref === cur.ref) i++;
      if (i >= speech.items.length) return;
    } else {
      while (i > 0 && speech.items[i - 1].ref === cur.ref) i--;
      if (i > 0) {
        const prevRef = speech.items[i - 1].ref;
        i--;
        while (i > 0 && speech.items[i - 1].ref === prevRef) i--;
      }
    }
    haptic('tick');
    readerUserScrollAt = 0;
    speechFrom(i);
  }

  function openReaderStyle() {
    openSheet('reader-style', (s) => {
      const draw = () => {
        s.textContent = '';
        s.append(el('div', { class: 'sheet-head' }, el('div', { class: 'sh-text' }, el('div', { class: 'sh-title', text: 'Text and colours' }))));
        const idx = Math.max(0, READER_SIZES.indexOf(settings.reader.size));
        const change = (d) => {
          const next = READER_SIZES[Math.max(0, Math.min(READER_SIZES.length - 1, idx + d))];
          if (next === settings.reader.size) return haptic('reject');
          settings.reader.size = next;
          haptic('tick');
          saveSettings();
          applyReaderLook();
          draw();
        };
        const dots = el('div', { class: 'rs-dots' });
        READER_SIZES.forEach((sz, i) => dots.append(el('i', { class: i <= idx ? 'on' : '' })));
        s.append(el('div', { class: 'rs-size' },
          el('button', { class: 'rs-btn', 'aria-label': 'Smaller text', onclick: () => change(-1) }, el('span', { style: 'font-size:15px', text: 'A' })),
          dots,
          el('button', { class: 'rs-btn', 'aria-label': 'Bigger text', onclick: () => change(1) }, el('span', { style: 'font-size:24px', text: 'A' }))));
        const fonts = el('div', { class: 'seg', style: 'margin:6px 20px 0' });
        [['serif', 'Serif'], ['sans', 'Sans']].forEach(([f, label]) => fonts.append(el('button', { class: (settings.reader.font === f ? 'on ' : '') + 'font-' + f, text: label, onclick: () => {
          settings.reader.font = f;
          haptic();
          saveSettings();
          applyReaderLook();
          draw();
        } })));
        s.append(fonts);
        const themes = el('div', { class: 'rs-themes' });
        [['auto', 'Auto'], ['light', 'Light'], ['sepia', 'Sepia'], ['dark', 'Dark']].forEach(([th, label]) => themes.append(el('button', { class: 'rs-theme th-' + th + (settings.reader.theme === th ? ' on' : ''), onclick: () => {
          settings.reader.theme = th;
          haptic();
          saveSettings();
          applyReaderLook();
          lastModeSig = '';
          syncMode();
          draw();
        } }, el('span', { class: 'rs-swatch', text: 'Aa' }), el('span', { text: label }))));
        s.append(themes);
        window.fillIcons(s);
      };
      draw();
    });
  }

  function setupReader() {
    const r = $('#reader');
    $('#reader-close').onclick = () => closeScreen();
    $('#reader-aa').onclick = () => openReaderStyle();
    $('#reader-listen').onclick = () => {
      haptic();
      if (speech.owner === 'reader' && speech.playing) pauseSpeech();
      else if (speech.owner === 'reader' && speech.items.length) resumeSpeech();
      else startReaderListen(0);
    };
    $('#rp-play').onclick = () => {
      haptic();
      if (speech.playing) pauseSpeech();
      else resumeSpeech();
    };
    $('#rp-prev').onclick = () => readerJump(-1);
    $('#rp-next').onclick = () => readerJump(1);
    $('#rp-close').onclick = () => {
      haptic();
      stopSpeech();
    };
    $('#rp-rate').onclick = () => {
      const rates = [1, 1.25, 1.5, 1.75, 2, 0.75];
      const i = rates.indexOf(settings.speechRate || 1);
      settings.speechRate = rates[(i + 1) % rates.length];
      saveSettings();
      haptic('tick');
      if (speech.playing) speechFrom(speech.index);
      else updateReaderPlayer();
    };
    // Tap a paragraph while listening to jump there.
    $('#reader-body').addEventListener('click', (e) => {
      if (speech.owner !== 'reader' || !reader) return;
      if (String(window.getSelection ? window.getSelection() : '').trim()) return;
      const i = reader.items.findIndex((it) => it.ref && (it.ref === e.target || it.ref.contains(e.target)));
      if (i >= 0 && i !== speech.index) {
        haptic('tick');
        readerUserScrollAt = 0;
        speechFrom(i);
      }
    });
    // The top bar tucks away while you read down, and comes back when you scroll up.
    let lastTop = 0;
    let ticking = false;
    r.addEventListener('scroll', () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        ticking = false;
        const top = r.scrollTop;
        if (top > lastTop + 8 && top > 90) r.classList.add('hide-top');
        else if (top < lastTop - 8 || top < 40) r.classList.remove('hide-top');
        lastTop = top;
        renderReaderProgress();
      });
    }, { passive: true });
    ['touchstart', 'wheel'].forEach((ev) => r.addEventListener(ev, () => {
      readerUserScrollAt = Date.now();
    }, { passive: true }));
    speechListeners.push(() => {
      if (screen === 'reader' || !$('#reader').hidden) updateReaderPlayer();
    });
  }

