  function onVoice(e) {
    if (e.error) {
      if (e.error === 'unavailable') toast('Voice typing isn’t available on this ' + deviceWord());
      else if (e.error === 'nothing') toast('Didn’t catch that. Try again');
      return;
    }
    if (!e.text) return;
    if (e.target === 'ai') {
      if (screen !== 'ai') ai.open();
      ai.ask(e.text, { voice: true });
      return;
    }
    // Show what was heard for a moment, then go.
    if (screen !== 'search') openSearch('', {});
    const q = $('#q');
    q.value = e.text;
    onQueryInput({ inputType: 'insertText' });
    q.blur();
    setTimeout(() => {
      if (screen === 'search' && q.value === e.text) navigate(e.text);
    }, 450);
  }

  // ------------------------------------------------------------------------------------------
  // Touch: drag sheets down to close them (with momentum), and ripples where you tap
  // ------------------------------------------------------------------------------------------

  /**
   * panel follows the finger; scrim fades with it. opts.canStart(touchY, panelRect) decides if a
   * downward drag should move the panel; opts.dismiss(ms) closes it from where the finger let go.
   */
  function makeDraggable(panel, scrim, opts) {
    let startY = 0;
    let lastY = 0;
    let lastT = 0;
    let vy = 0;
    let decided = false;
    let dragging = false;
    let allowed = false;
    let pastThreshold = false;
    let h = 1;
    panel.addEventListener('touchstart', (e) => {
      if (!opts.active() || e.touches.length > 1) return;
      const y = e.touches[0].clientY;
      startY = lastY = y;
      lastT = e.timeStamp;
      vy = 0;
      decided = false;
      dragging = false;
      pastThreshold = false;
      h = Math.max(1, panel.offsetHeight);
      allowed = opts.canStart(y, panel.getBoundingClientRect(), e.target);
    }, { passive: true });
    panel.addEventListener('touchmove', (e) => {
      if (!allowed || !opts.active()) return;
      const y = e.touches[0].clientY;
      const dy = y - startY;
      if (!decided) {
        if (Math.abs(dy) < 6) return;
        decided = true;
        dragging = dy > 0;
        if (dragging) {
          panel.classList.add('dragging');
          if (scrim) scrim.classList.add('dragging');
          panel.style.transition = 'none';
          if (scrim) scrim.style.transition = 'none';
        }
      }
      if (!dragging) return;
      if (e.cancelable) e.preventDefault();
      const dt = Math.max(1, e.timeStamp - lastT);
      vy = 0.7 * ((y - lastY) / dt) + 0.3 * vy;
      lastY = y;
      lastT = e.timeStamp;
      const off = dy > 0 ? dy : dy * 0.2;
      panel.style.transform = 'translate3d(0,' + off.toFixed(1) + 'px,0)';
      if (scrim) scrim.style.opacity = String(Math.max(0, 1 - off / h));
      // A light tick when letting go would close it (and again if you pull back).
      const past = off > h * 0.28;
      if (past !== pastThreshold) {
        pastThreshold = past;
        haptic('tick');
      }
    }, { passive: false });
    const end = () => {
      if (!dragging) return;
      dragging = false;
      panel.classList.remove('dragging');
      if (scrim) scrim.classList.remove('dragging');
      const dy = lastY - startY;
      if (dy > h * 0.28 || (vy > 0.5 && dy > 24)) {
        // Fling: finish at the speed the finger was moving.
        const ms = Math.round(Math.max(150, Math.min(340, (h - dy) / Math.max(0.9, vy))));
        if (!pastThreshold) haptic('tick');
        panel.style.transition = 'transform ' + ms + 'ms cubic-bezier(0.25, 0.8, 0.35, 1)';
        panel.style.transform = 'translate3d(0,' + (h + 40) + 'px,0)';
        if (scrim) {
          scrim.style.transition = 'opacity ' + ms + 'ms ease';
          scrim.style.opacity = '0';
        }
        opts.dismiss(ms);
      } else {
        // Not far enough: spring back.
        panel.style.transition = 'transform 0.5s var(--spring-sheet)';
        panel.style.transform = '';
        if (scrim) {
          scrim.style.transition = 'opacity 0.3s ease';
          scrim.style.opacity = '';
        }
        setTimeout(() => {
          if (!panel.classList.contains('dragging')) {
            panel.style.transition = '';
            if (scrim) scrim.style.transition = '';
          }
        }, 520);
      }
    };
    panel.addEventListener('touchend', end);
    panel.addEventListener('touchcancel', end);
  }

  function setupDrag() {
    const s = $('#sheet');
    const b = $('#backdrop');
    makeDraggable(s, b, {
      active: () => !!sheet && !s.classList.contains('anim-out'),
      canStart: (y, rect, target) => y - rect.top < 40 || (s.scrollTop <= 0 && !(target.closest && target.closest('input,textarea,.rs-dots'))),
      dismiss: (ms) => {
        sheet = null;
        closing++;
        setTimeout(() => {
          closing = Math.max(0, closing - 1);
          if (!sheet) {
            s.hidden = true;
            b.hidden = true;
          }
          s.style.transition = s.style.transform = b.style.transition = b.style.opacity = '';
          update();
        }, ms + 20);
      },
    });
    const panel = $('.ai-panel');
    const scrim = $('#ai-scrim');
    makeDraggable(panel, scrim, {
      active: () => screen === 'ai',
      canStart: (y, rect, target) => y - rect.top < 56 && !(target.closest && target.closest('button')),
      dismiss: (ms) => {
        $('#ai-q').blur();
        screen = null;
        closingScreen = 'ai';
        closing++;
        setTimeout(() => {
          closing = Math.max(0, closing - 1);
          if (closingScreen === 'ai') closingScreen = null;
          panel.style.transition = panel.style.transform = scrim.style.transition = scrim.style.opacity = '';
          update();
        }, ms + 20);
      },
    });
  }

  const RIPPLE = 'button.sheet-item, button.set-row, .row, .sugg, .quick button, .check-row, .lang, .rs-theme';

  // Liquid Glass on iPhone/iPad: pressed glass lifts and lights up where you touch it.
  const GLASS_PRESS = '.btn, .icon-btn, .chip, .fab, .home-ai, .home-search, .ai-chip, .space-chip, .quick button, .ai-send, .rs-btn, .tab-card, '
    + 'button.sheet-item, button.set-row, .sugg, .row, .check-row, .lang, .rs-theme, #pill-text';

  function setupGlass() {
    document.addEventListener('pointerdown', (e) => {
      const t = e.target.closest && e.target.closest(GLASS_PRESS);
      if (!t || t.disabled) return;
      const r = t.getBoundingClientRect();
      t.classList.add('lg-down');
      let glow = null;
      if (!reducedMotion && !t.classList.contains('tab-card')) {
        glow = document.createElement('span');
        glow.className = 'lg-glow';
        glow.style.left = e.clientX - r.left + 'px';
        glow.style.top = e.clientY - r.top + 'px';
        t.append(glow);
      }
      let done = false;
      const up = () => {
        if (done) return;
        done = true;
        window.removeEventListener('pointerup', up);
        window.removeEventListener('pointercancel', up);
        t.classList.remove('lg-down');
        if (glow) {
          glow.classList.add('out');
          setTimeout(() => glow.remove(), 520);
        }
      };
      window.addEventListener('pointerup', up);
      window.addEventListener('pointercancel', up);
      setTimeout(up, 1500);
    }, { passive: true });

    // Segmented choices: a glass lens slides (and briefly stretches, like liquid) to the chosen one.
    let raf = 0;
    const place = () => {
      raf = 0;
      $$('.seg').forEach((seg) => {
        const on = seg.querySelector(':scope > button.on');
        let lens = seg.querySelector(':scope > .lg-lens');
        if (!on || !seg.offsetWidth) {
          if (lens) lens.style.opacity = '0';
          return;
        }
        const pos = [on.offsetLeft, on.offsetTop, on.offsetWidth, on.offsetHeight].join(',');
        if (!lens) {
          lens = document.createElement('i');
          lens.className = 'lg-lens';
          lens.style.transition = 'none';
          seg.prepend(lens);
          seg.classList.add('lg-ready');
        }
        if (lens.dataset.pos === pos) return;
        const moved = !!lens.dataset.pos;
        lens.dataset.pos = pos;
        lens.style.translate = on.offsetLeft + 'px ' + on.offsetTop + 'px';
        lens.style.width = on.offsetWidth + 'px';
        lens.style.height = on.offsetHeight + 'px';
        lens.style.opacity = '1';
        if (moved && !reducedMotion) {
          lens.classList.remove('moving');
          void lens.offsetWidth;
          lens.classList.add('moving');
          clearTimeout(lens.tpTimer);
          lens.tpTimer = setTimeout(() => lens.classList.remove('moving'), 600);
        } else {
          requestAnimationFrame(() => {
            lens.style.transition = '';
          });
        }
      });
    };
    const schedule = () => {
      if (!raf) raf = requestAnimationFrame(place);
    };
    new MutationObserver(schedule).observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['class', 'hidden'] });
    window.addEventListener('resize', schedule);
    schedule();
  }

  function setupRipples() {
    if (IOS) return setupGlass();
    document.addEventListener('pointerdown', (e) => {
      if (reducedMotion || !e.target.closest) return;
      const t = e.target.closest(RIPPLE);
      if (!t || t.disabled || e.target.closest('.sugg-fill, .icon-btn')) return;
      const r = t.getBoundingClientRect();
      const size = Math.max(r.width, r.height) * 2.1;
      const dot = document.createElement('span');
      dot.className = 'ripple';
      dot.style.width = dot.style.height = size + 'px';
      dot.style.left = e.clientX - r.left - size / 2 + 'px';
      dot.style.top = e.clientY - r.top - size / 2 + 'px';
      t.append(dot);
      let done = false;
      const fade = () => {
        if (done) return;
        done = true;
        window.removeEventListener('pointerup', fade);
        window.removeEventListener('pointercancel', fade);
        dot.classList.add('fade');
        setTimeout(() => dot.remove(), 450);
      };
      window.addEventListener('pointerup', fade);
      window.addEventListener('pointercancel', fade);
      setTimeout(fade, 1500);
    }, { passive: true });
  }

