  function relTime(ts) {
    return new Date(ts).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
  }

  function renderHistory() {
    const list = $('#history-list');
    list.textContent = '';
    const q = $('#history-q').value.trim().toLowerCase();
    const items = (q ? history.filter((h) => (h.title || '').toLowerCase().indexOf(q) >= 0 || h.url.toLowerCase().indexOf(q) >= 0) : history).slice(0, 400);
    if (!items.length) {
      list.append(el('div', { class: 'empty', text: q ? 'Nothing matches “' + q + '”' : 'Sites you visit will show up here' }));
      return;
    }
    C.groupByDay(items).forEach((g) => {
      list.append(el('div', { class: 'group-label', text: g.label }));
      g.items.forEach((h) => {
        const row = el('div', { class: 'row', onclick: () => navigate(h.url) },
          siteIcon(h.url, h.title, 'row-icon'),
          el('div', { class: 'row-text' }, el('div', { class: 'row-title', text: h.title || C.hostOf(h.url) }), el('div', { class: 'row-sub', text: C.hostOf(h.url) + ' · ' + relTime(h.ts) })),
          el('button', { class: 'icon-btn', 'aria-label': 'Remove', onclick: (e) => {
            e.stopPropagation();
            history = history.filter((x) => x !== h);
            indexCache = null;
            saveHistory();
            row.remove();
          } }, icon('close')));
        list.append(row);
      });
    });
  }

  function renderFavorites() {
    const list = $('#fav-list');
    list.textContent = '';
    if (!bookmarks.length) {
      list.append(el('div', { class: 'empty', text: 'Tap ☆ Favorite in the menu on any site to add it here' }));
      return;
    }
    bookmarks.forEach((b, i) => {
      list.append(el('div', { class: 'row', onclick: () => navigate(b.url) },
        siteIcon(b.url, b.title, 'row-icon', true, true),
        el('div', { class: 'row-text' }, el('div', { class: 'row-title', text: b.title }), el('div', { class: 'row-sub', text: C.hostOf(b.url) })),
        i > 0 ? el('button', { class: 'icon-btn', 'aria-label': 'Move up', onclick: (e) => {
          e.stopPropagation();
          bookmarks.splice(i, 1);
          bookmarks.splice(i - 1, 0, b);
          saveBookmarks();
          renderFavorites();
        } }, icon('up')) : null,
        el('button', { class: 'icon-btn', 'aria-label': 'Remove', onclick: (e) => {
          e.stopPropagation();
          bookmarks.splice(i, 1);
          indexCache = null;
          saveBookmarks();
          renderFavorites();
        } }, icon('trash'))));
