    const sw = switchEl(get());
    const row = el('button', { class: 'set-row', onclick: () => {
      set(!get());
      sw.classList.toggle('on', get());
      haptic();
    } }, el('div', { class: 'set-text' }, el('div', { text: title }), sub ? el('div', { class: 'set-sub', text: sub }) : null), sw);
