    home.card.append(el('div', { class: 'set-block' }, el('div', { class: 'set-title', text: 'Wallpaper' }), sw));
    home.card.append(el('button', { class: 'set-row', onclick: () => openScreen('favorites') }, el('div', { class: 'set-text' }, el('div', { text: 'Favorites' }), el('div', { class: 'set-sub', text: bookmarks.length + ' sites' })), icon('chevron')));
    body.append(home.g);

