  function swatchBackground(id) {
    switch (id) {
      case 'aurora':
        return 'linear-gradient(180deg, #1e1b4b, #3b2a8a 45%, #0f766e)';
      case 'sunset':
        return 'linear-gradient(180deg, #3b1673, #9d2a8a 45%, #f97316)';
      case 'ocean':
        return 'linear-gradient(180deg, #0c2d6b, #1d4ed8 50%, #06b6d4)';
      case 'forest':
        return 'linear-gradient(180deg, #052e16, #166534 50%, #4d7c0f)';
      case 'midnight':
        return 'linear-gradient(180deg, #0b1026, #1e1b4b 55%, #312e81)';
      case 'custom':
        return wallpaperPhoto ? 'center / cover url("' + wallpaperPhoto + '")' : 'repeating-linear-gradient(45deg, #8882 0 8px, #8883 8px 16px)';
      default:
        return 'radial-gradient(60px 60px at 80% 30%, color-mix(in oklab, var(--c2) 35%, transparent), transparent), radial-gradient(70px 70px at 10% 70%, color-mix(in oklab, var(--c1) 30%, transparent), transparent), var(--bg)';
    }
  }

  function setupPhotoPicker() {
    $('#photo-input').addEventListener('change', (e) => {
      const file = e.target.files && e.target.files[0];
      e.target.value = '';
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        const img = new Image();
        img.onload = () => {
          const scale = Math.min(1, 1440 / Math.max(img.width, img.height));
          const canvas = document.createElement('canvas');
          canvas.width = Math.round(img.width * scale);
          canvas.height = Math.round(img.height * scale);
          canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
          wallpaperPhoto = canvas.toDataURL('image/jpeg', 0.84);
          N.save('wallpaper', JSON.stringify(wallpaperPhoto));
          settings.wallpaper = 'custom';
          saveSettings();
          applyWallpaper();
          if (screen === 'settings') renderSettings('home');
          toast('Wallpaper set');
        };
        img.onerror = () => toast("That photo couldn't be opened");
        img.src = reader.result;
      };
      reader.readAsDataURL(file);
    });
  }

