  function openFind() {
    const t = pageTab();
    if (!t) return;
    findOpen = true;
    $('#findbar').hidden = false;
    $('#mainbar').hidden = true;
    $('#find-q').value = '';
    $('#find-count').textContent = '';
    update();
    $('#find-q').focus();
  }

  function closeFind() {
    if (!findOpen) return;
    findOpen = false;
    const t = activeTab();
    if (t && t.live) N.find(t.id, '', 2);
    $('#find-q').blur();
    $('#findbar').hidden = true;
    $('#mainbar').hidden = false;
  }

  function setupFind() {
    $('#find-q').addEventListener('input', (e) => {
      const t = pageTab();
      if (t) N.find(t.id, e.target.value, 0);
      if (!e.target.value) $('#find-count').textContent = '';
    });
    $('#find-q').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const t = pageTab();
        if (t) N.find(t.id, '', 1);
      }
    });
    $('#find-next').onclick = () => {
      const t = pageTab();
      if (t) N.find(t.id, '', 1);
    };
    $('#find-prev').onclick = () => {
      const t = pageTab();
      if (t) N.find(t.id, '', -1);
    };
    $('#find-close').onclick = () => {
      closeFind();
      update();
    };
  }

