  // Focus and shield plumbing
  // ------------------------------------------------------------------------------------------

  function pushShield() {
    N.setShield(!!settings.shield, !!settings.ytSkip, settings.shieldAllow.join(','));
    if (!Array.isArray(settings.popupAllow)) settings.popupAllow = [];
    N.setPopupAllow(settings.popupAllow.join(','));
  }

  // Deeper check: watches what really happens when you tap (does the tap become a click? does the
  // page keep drawing frames? can it play sound?) so a broken page can be diagnosed from a report.
  const TRACE_START = "(function(){var T=window.__tpTrace;if(T){T.events=[];T.start=Date.now();T.frames=0;return 'reset';}" +
    "T=window.__tpTrace={events:[],rejections:[],errors:[],frames:0,start:Date.now()};" +
    "var d=function(el){try{if(!el||!el.tagName)return String(el&&el.nodeName);var s=el.tagName.toLowerCase();if(el.id)s+='#'+el.id;" +
    "var c=(typeof el.className==='string'?el.className:'').trim().split(/\\s+/).slice(0,2).join('.');if(c)s+='.'+c.slice(0,50);" +
    "var tx=(el.innerText||'').trim().replace(/\\s+/g,' ').slice(0,24);if(tx)s+=' \"'+tx+'\"';return s;}catch(e){return '?';}};" +
    "var add=function(x){T.events.push(x);if(T.events.length>40)T.events.shift();};" +
    "['pointerdown','pointerup','pointercancel','touchstart','touchend','touchcancel','mousedown','mouseup','click'].forEach(function(ty){" +
    "window.addEventListener(ty,function(e){add((Date.now()-T.start)+'ms '+ty+' '+d(e.target)+(e.isTrusted?'':' untrusted'));},true);" +
    "window.addEventListener(ty,function(e){if(ty==='click'||ty==='touchend')add('   '+ty+' reached page end'+(e.defaultPrevented?' (default prevented)':''));},false);});" +
    "window.addEventListener('click',function(){if(T.audio)return;try{var ac=new (window.AudioContext||window.webkitAudioContext)();T.audio=ac.state;" +
    "ac.resume().then(function(){T.audio+=' -> resume ok '+ac.state;},function(e){T.audio+=' -> resume failed '+e;});setTimeout(function(){if(T.audio.indexOf('->')<0)T.audio+=' -> resume hung';},1500);}catch(e){T.audio='error '+e;}},true);" +
    "window.addEventListener('unhandledrejection',function(e){T.rejections.push(String(e.reason&&(e.reason.stack||e.reason.message)||e.reason).slice(0,200));});" +
    "window.addEventListener('error',function(e){T.errors.push(String(e.message||e.type)+(e.target&&e.target.src?' '+e.target.src:'').slice(0,200));},true);" +
    "var tick=function(){T.frames++;requestAnimationFrame(tick);};requestAnimationFrame(tick);return 'started';})()";

  const TRACE_READ = "(function(){var T=window.__tpTrace;var u=navigator.userAgentData;var f=[].slice.call(document.querySelectorAll('iframe')).map(function(x){return (x.src||'(no src)').slice(0,80);}).slice(0,5);" +
    "var o={visibility:document.visibilityState,focus:document.hasFocus(),ua:navigator.userAgent,brands:u?JSON.stringify(u.brands)+' mobile='+u.mobile+' platform='+u.platform:'none'," +
    "apis:'speech='+(typeof speechSynthesis)+' notification='+(typeof Notification)+' chrome='+(typeof window.chrome)+' vibrate='+(typeof navigator.vibrate)+' share='+(typeof navigator.share)," +
    "iframes:f,size:innerWidth+'x'+innerHeight+' dpr '+devicePixelRatio};" +
    "if(T){var secs=Math.max(0.5,(Date.now()-T.start)/1000);o.fps=Math.round(T.frames/secs);o.events=T.events;o.rejections=T.rejections;o.errors=T.errors;o.audio=T.audio||'not tested';}else{o.trace='not started';}" +
    "return JSON.stringify(o);})()";

  function startDeepCheck(t) {
    evalInTab(t.id, TRACE_START).then(() => {
      t.deepCheck = true;
      toast('Deeper check on. Tap the button that doesn’t work once, then ⋮ → Page not working? → Copy a problem report');
    });
  }

  /** Help for a page that doesn't work, plus a report Tonpoon can send to get it fixed. */
  function openProblemSheet() {
    const t = pageTab();
    if (!t) return;
    const real = C.realUrl(t.url) || t.url;
    const root = C.rootDomain(C.hostOf(real));
    let info = {};
    try {
      info = JSON.parse(N.pageReport(t.id) || '{}');
    } catch (e) {
      info = {};
    }
    const errors = Array.isArray(info.errors) ? info.errors : [];
    const popupsOk = (settings.popupAllow || []).indexOf(root) >= 0;
    openSheet('problem', (s) => {
      s.append(el('div', { class: 'sheet-hero' },
        el('div', { class: 'hero-icon', style: 'background:var(--accent-soft)', text: '🧰' }),
        el('h3', { text: 'Page not working?' }),
        el('p', { text: 'Try these one at a time on ' + root + '.' })));
      s.append(sheetItem('reload', 'Reload the page', () => { closeSheet(); N.nav(t.id, 'reload'); }));
      if (info.shield) {
        s.append(sheetItem('shieldOff', 'Turn off TP Shield here', () => { toggleSiteShield(t); closeSheet(); }, { sub: 'Ad and tracker blocking can stop some buttons' }));
      }
      s.append(sheetItem('bgtab', popupsOk ? 'Pop-ups are allowed here' : 'Allow pop-ups here', () => {
        settings.popupAllow = popupsOk ? settings.popupAllow.filter((d) => d !== root) : settings.popupAllow.concat([root]);
        saveSettings();
        pushShield();
        closeSheet();
        toast(popupsOk ? 'Pop-ups blocked on ' + root : 'Pop-ups allowed on ' + root + '. Try the button again');
      }, { sub: info.popupsBlocked ? info.popupsBlocked + ' pop-up' + (info.popupsBlocked > 1 ? 's' : '') + ' blocked on this page' : 'Some buttons open a new window', right: switchEl(popupsOk) }));
      s.append(sheetItem('desktop', t.desktop ? 'Back to mobile site' : 'Try the desktop site', () => {
        t.desktop = !t.desktop;
        N.setDesktop(t.id, t.desktop);
        closeSheet();
      }));
      s.append(sheetItem('external', 'Open in another browser', () => { closeSheet(); N.openExternal(real); }));
      if (!t.deepCheck) {
        s.append(sheetItem('find', 'Start a deeper check', () => { closeSheet(); startDeepCheck(t); }, { sub: 'Then tap the broken button once and copy the report' }));
      }
      s.append(sheetItem('copy', 'Copy a problem report', async () => {
        let deep = '';
        if (t.deepCheck) {
          const r = await evalInTab(t.id, TRACE_READ, 4000);
          let d = {};
          try {
            d = JSON.parse(JSON.parse(r.result || '""') || '{}');
          } catch (e) {
            d = { error: r.error || 'could not read' };
          }
          deep = [
            'Deeper check: visibility ' + d.visibility + ' · focus ' + d.focus + ' · fps ' + d.fps + ' · size ' + d.size,
            'Sound: ' + d.audio,
            'APIs: ' + d.apis,
            'UA: ' + d.ua,
            'Brands: ' + d.brands,
            'Frames: ' + (d.iframes && d.iframes.length ? d.iframes.join(', ') : 'none'),
            d.trace === 'not started' ? 'Taps: (the page reloaded, so start the deeper check again)' : 'Taps:\n' + ((d.events || []).join('\n') || '(no tap reached the page)'),
            (d.rejections || []).length ? 'Promise errors:\n' + d.rejections.join('\n') : '',
            (d.errors || []).length ? 'Load errors:\n' + d.errors.join('\n') : '',
            d.error ? 'Check failed: ' + d.error : '',
          ].filter(Boolean).join('\n');
          if (d.trace === 'not started') t.deepCheck = false;
        }
        const report = [
          'TP Browser ' + (info.version || BUILD.version) + (IOS ? ' · iOS ' + (info.ios || '') + ' · interface ' + (info.ui || BUILD.version) : ' · Android ' + (info.android || '') + ' · engine ' + (info.webview || '')),
          'Page: ' + real,
          'Shield: ' + (info.shield ? 'on' : 'off') + ' · blocked ' + (info.blocked || 0) + ' · pop-ups blocked ' + (info.popupsBlocked || 0) + ' · desktop site ' + (info.desktop ? 'on' : 'off'),
          errors.length ? 'Page errors:\n' + errors.slice(-15).join('\n') : 'Page errors: none',
          deep,
        ].filter(Boolean).join('\n');
        N.copy(report);
        closeSheet();
        toast('Report copied. Paste it to Claude to get it fixed');
      }, { sub: errors.length ? errors.length + ' error' + (errors.length > 1 ? 's' : '') + ' on this page' : 'No errors so far' }));
    });
  }

