    N.setFocus(settings.focusEndsAt || 0, settings.focusSites.join(','));
  }

  function startFocus(minutes) {
    settings.focusMinutes = minutes;
    settings.focusStartedAt = Date.now();
    settings.focusEndsAt = Date.now() + minutes * 60000;
    saveSettings();
    pushFocus();
    tabs.forEach((t) => {
      if (t.live && !t.home && C.hostInList(C.hostOf(t.url), settings.focusSites)) N.loadUrl(t.id, C.realUrl(t.url) || t.url);
    });
    toast('Focus on for ' + minutes + ' min. You got this! 🎯');
    update();
  }

  function endFocus(early) {
    if (!settings.focusStartedAt) return;
    const end = Math.min(Date.now(), settings.focusEndsAt || Date.now());
    const minutes = Math.max(0, (end - settings.focusStartedAt) / 60000);
    const k = C.dayKey();
    stats.focus[k] = (Number(stats.focus[k]) || 0) + Math.round(minutes);
    stats.focus = C.pruneDays(stats.focus, 60);
    saveStats();
    settings.focusStartedAt = 0;
    settings.focusEndsAt = 0;
    saveSettings();
    pushFocus();
    tabs.forEach((t) => {
      if (t.live && /focus\.html/.test(t.url || '') && C.isTpPage(t.url)) N.loadUrl(t.id, C.realUrl(t.url));
    });
    if (!early) toast('Focus session done! ' + Math.round(minutes) + ' minutes 🎉');
    update();
  }

  // ------------------------------------------------------------------------------------------
  // Native bridge plumbing
  // ------------------------------------------------------------------------------------------

  let fetchSeq = 0;
  const pendingFetches = new Map();

  function nativeFetch(url, timeout) {
    return new Promise((resolve) => {
      const id = 'f' + ++fetchSeq;
      pendingFetches.set(id, resolve);
      N.fetch(id, url);
      setTimeout(() => {
        if (pendingFetches.has(id)) {
          pendingFetches.delete(id);
          resolve(null);
        }
      }, timeout || 12000);
    });
  }

  /** Any request (GET/POST, optionally streamed) through the native side. Returns { promise, abort }. */
  const pendingRequests = new Map();

  function nativeRequest(url, opts) {
    opts = opts || {};
    const id = 'q' + ++fetchSeq;
    let resolveFn;
    const promise = new Promise((resolve) => {
      resolveFn = resolve;
    });
    const entry = { resolve: resolveFn, onChunk: opts.onChunk };
    entry.timer = setTimeout(() => {
      if (pendingRequests.has(id)) {
        pendingRequests.delete(id);
        N.abort(id);
        resolveFn({ status: 0, body: '', error: 'timeout' });
      }
    }, opts.timeout || 60000);
    pendingRequests.set(id, entry);
    N.request(id, url, opts.method || 'GET', JSON.stringify(opts.headers || {}), opts.body || '', !!opts.stream);
    return {
      promise,
      abort() {
        if (!pendingRequests.has(id)) return;
        pendingRequests.delete(id);
        clearTimeout(entry.timer);
        N.abort(id);
        resolveFn({ status: 0, body: '', aborted: true });
      },
    };
  }

  const pendingEvals = new Map();
  let evalSeq = 0;

  function evalInTab(tabId, script, timeout) {
    return new Promise((resolve) => {
      const id = 'e' + ++evalSeq;
      const timer = setTimeout(() => {
        pendingEvals.delete(id);
        resolve({ error: 'The page took too long to answer' });
      }, timeout || 10000);
      pendingEvals.set(id, { resolve, timer });
      N.evalInTab(id, tabId, script);
    });
  }

  const loadWaiters = new Map();

  function waitForLoad(tabId, timeout) {
    return new Promise((resolve) => {
      const t = tab(tabId);
      if (!t) return resolve(false);
      const list = loadWaiters.get(tabId) || [];
      const done = (ok) => {
        clearTimeout(timer);
        resolve(ok);
      };
      const timer = setTimeout(() => {
        const l = loadWaiters.get(tabId) || [];
        loadWaiters.set(tabId, l.filter((f) => f !== done));
        resolve(false);
      }, timeout || 12000);
      list.push(done);
      loadWaiters.set(tabId, list);
      // Already finished loading (and not just started)?
      setTimeout(() => {
        const cur = tab(tabId);
        if (cur && !cur.loading && cur.url && (loadWaiters.get(tabId) || []).indexOf(done) >= 0) {
          loadWaiters.set(tabId, (loadWaiters.get(tabId) || []).filter((f) => f !== done));
          done(true);
        }
      }, 1200);
    });
  }

  function resolveLoadWaiters(tabId) {
    const list = loadWaiters.get(tabId);
    if (!list || !list.length) return;
    loadWaiters.delete(tabId);
    // Give the page a moment to render its text after the load event.
    setTimeout(() => list.forEach((f) => f(true)), 400);
  }

  // ------------------------------------------------------------------------------------------
  // In-app updates: check TP's update feed, download in the background, install on a tap
  // ------------------------------------------------------------------------------------------

  let updateInfo = null;
  let pendingInstall = false;
  let updateToastShown = false;

  async function checkForUpdates(manual) {
    if (!BUILD.updateUrl) {
      if (manual) toast('Updates are not set up in this version yet');
      return;
    }
    settings.lastUpdateCheck = Date.now();
    saveSettings();
    const r = await nativeRequest(BUILD.updateUrl + (BUILD.updateUrl.indexOf('?') >= 0 ? '&' : '?') + 't=' + Math.floor(Date.now() / 60000), { headers: { Accept: 'application/json' }, timeout: 20000 }).promise;
    let info = null;
    try {
      info = JSON.parse(r.body);
    } catch (e) {
      info = null;
    }
    if (!info || !info.versionCode || !info.apk) {
      if (manual) toast(r.status === 0 ? "Couldn't check for updates. Check your connection." : "Couldn't read the update information");
      return;
    }
    if (Number(info.versionCode) <= Number(BUILD.versionCode)) {
      if (manual) toast('TP Browser is up to date ✓');
      if (screen === 'settings') renderSettings('updates');
      return;
    }
    if (updateInfo && updateInfo.versionCode === info.versionCode && updateInfo.state !== 'failed') {
      if (manual) openUpdateSheet();
      return;
    }
    updateInfo = Object.assign({}, info, { state: 'available', p: 0 });
    if (settings.autoUpdate !== false) startUpdateDownload();
    if (manual) openUpdateSheet();
    update();
  }

  function startUpdateDownload() {
    if (!updateInfo) return;
    updateInfo.state = 'downloading';
    updateInfo.p = 0;
    N.downloadUpdate(updateInfo.apk, updateInfo.sha256 || '');
    refreshUpdateUi();
  }

  function installUpdateNow() {
    if (!updateInfo) return;
    flushSaves();
    if (!N.canInstall()) {
      pendingInstall = true;
      openSheet('update-permission', (s) => {
        s.append(el('div', { class: 'sheet-hero' },
          el('div', { class: 'hero-icon', style: 'background:var(--accent-soft)', text: '🔓' }),
          el('h3', { text: 'One-time step' }),
          el('p', { text: 'Android needs your OK for TP Browser to install its own updates. Turn on “Allow from this source”, then come back.' })));
        s.append(el('div', { class: 'sheet-actions' },
          el('button', { class: 'btn ghost', text: 'Not now', onclick: () => { pendingInstall = false; closeSheet(); } }),
          el('button', { class: 'btn', text: 'Open settings', onclick: () => { closeSheet(); N.allowInstalls(); } })));
      });
      return;
    }
    updateInfo.state = 'installing';
    refreshUpdateUi();
    N.installUpdate();
  }

  function onUpdateEvent(e) {
    if (!updateInfo) updateInfo = { version: e.version || '', state: e.state };
    updateInfo.state = e.state;
    if (e.state === 'downloading') updateInfo.p = e.p;
    if (e.state === 'ready') {
      updateInfo.p = 100;
      if (!updateToastShown && sheet !== 'update') {
        updateToastShown = true;
        toast('TP Browser ' + (updateInfo.version || e.version || '') + ' is ready to install ✨');
      }
    }
    if (e.state === 'failed') updateInfo.message = e.message || 'Something went wrong';
    if (e.state === 'cancelled') updateInfo.state = 'ready';
    refreshUpdateUi();
    update();
  }

  function refreshUpdateUi() {
    renderUpdateBanner();
    if (sheet === 'update') openUpdateSheet(true);
    if (screen === 'settings') {
      const st = $('#update-status');
      if (st) st.textContent = updateStatusText();
    }
  }

  function updateStatusText() {
    if (!updateInfo) return 'Version ' + (BUILD.version || '') + (settings.lastUpdateCheck ? ' · checked ' + new Date(settings.lastUpdateCheck).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : '');
    const v = updateInfo.version || '';
    switch (updateInfo.state) {
      case 'downloading':
        return 'Downloading ' + v + '… ' + (updateInfo.p >= 0 ? updateInfo.p + '%' : '');
      case 'ready':
        return v + ' is ready to install';
      case 'installing':
        return 'Installing ' + v + '…';
      case 'failed':
        return 'Update failed: ' + (updateInfo.message || '');
      default:
        return v + ' is available';
    }
  }

  function renderUpdateBanner() {
    const b = $('#update-banner');
    if (!b) return;
    const show = !!(updateInfo && (updateInfo.state === 'ready' || updateInfo.state === 'available' || updateInfo.state === 'failed'));
    b.hidden = !show;
    if (show) $('#update-banner-text').textContent = updateInfo.state === 'failed' ? 'Update didn’t finish · tap to retry' : 'TP Browser ' + (updateInfo.version || '') + ' is ready · Update';
  }

  function openUpdateSheet(refresh) {
    if (!updateInfo) return;
    const build = (s) => {
      const u = updateInfo;
      s.append(el('div', { class: 'sheet-hero' },
        el('div', { class: 'hero-icon logo', style: 'font-size:22px', text: 'TP' }),
        el('h3', { text: 'TP Browser ' + (u.version || '') }),
        el('p', { text: u.state === 'installing' ? 'Installing… TP will close and you can open it again.' : 'A new version is ready. Your tabs, favorites and settings stay.' })));
      if (Array.isArray(u.notes) && u.notes.length) {
        const ul = el('ul', { class: 'notes' });
        u.notes.slice(0, 8).forEach((n) => ul.append(el('li', { text: String(n) })));
        s.append(ul);
      }
      if (u.state === 'downloading') {
        s.append(el('div', { class: 'progress', style: 'margin:14px 24px 0' }, el('i', { style: 'width:' + Math.max(4, u.p || 0) + '%' })));
      }
      if (u.state === 'failed') s.append(el('p', { class: 'sheet-err', text: u.message || '' }));
      const actions = el('div', { class: 'sheet-actions' });
      actions.append(el('button', { class: 'btn ghost', text: 'Later', onclick: () => closeSheet() }));
      if (u.state === 'available' || u.state === 'failed') actions.append(el('button', { class: 'btn', text: 'Download', onclick: () => startUpdateDownload() }));
      else if (u.state === 'downloading') actions.append(el('button', { class: 'btn', disabled: true, text: 'Downloading… ' + (u.p >= 0 ? u.p + '%' : '') }));
      else if (u.state === 'ready') actions.append(el('button', { class: 'btn', text: 'Restart & update', onclick: () => installUpdateNow() }));
      else if (u.state === 'installing') actions.append(el('button', { class: 'btn', disabled: true, text: 'Installing…' }));
      s.append(actions);
    };
    if (refresh && sheet === 'update') {
      const s = $('#sheet');
      s.textContent = '';
      build(s);
      window.fillIcons(s);
    } else {
      openSheet('update', build);
    }
  }

  function versionCode(v) {
    const p = String(v || '').split('.').map((n) => parseInt(n, 10) || 0);
    return (p[0] || 0) * 10000 + (p[1] || 0) * 100 + (p[2] || 0);
  }

  /** What's new in every version after fromVersion (newest first), so skipped versions aren't missed. */
  function notesSince(fromVersion) {
    const all = BUILD.allNotes && typeof BUILD.allNotes === 'object' ? BUILD.allNotes : null;
    if (!all || !fromVersion) return Array.isArray(BUILD.notes) ? BUILD.notes : [];
    const from = versionCode(fromVersion);
    const to = versionCode(BUILD.version);
    const out = [];
    Object.keys(all)
      .filter((v) => versionCode(v) > from && versionCode(v) <= to)
      .sort((a, b) => versionCode(b) - versionCode(a))
      .forEach((v) => (Array.isArray(all[v]) ? all[v] : []).forEach((n) => out.push(n)));
    return out.length ? out : Array.isArray(BUILD.notes) ? BUILD.notes : [];
  }

  function showUpdateCompleted(fromVersion) {
    if (screen === 'welcome') return;
    if (sheet) return setTimeout(() => showUpdateCompleted(fromVersion), 1500);
    updateInfo = null;
    renderUpdateBanner();
    const notes = notesSince(fromVersion);
    openSheet('updated', (s) => {
      s.append(el('div', { class: 'sheet-hero' },
        el('div', { class: 'hero-icon done-icon' }, icon('check')),
        el('h3', { text: 'Update completed' }),
        el('p', { text: 'TP Browser ' + BUILD.version + (fromVersion ? ' (was ' + fromVersion + ')' : '') + ' · your settings, tabs and favorites are just as you left them.' })));
      if (notes.length) {
        s.append(el('div', { class: 'whatsnew-title', text: 'What’s new' }));
        const ul = el('ul', { class: 'whatsnew' });
        notes.slice(0, 12).forEach((n) => ul.append(el('li', { text: String(n) })));
        s.append(ul);
      }
      s.append(el('div', { class: 'sheet-actions' }, el('button', { class: 'btn', text: 'Nice!', onclick: () => closeSheet() })));
    });
  }

  function recordHistory(url, title) {
    if (!/^https?:/i.test(url)) return;
    const first = history[0];
    if (first && first.url === url) {
      if (title && title !== first.title) {
        first.title = title;
        saveHistory();
      }
      return;
    }
    history.unshift({ url, title: title || '', ts: Date.now() });
    if (history.length > 3000) history.length = 3000;
    indexCache = null;
    saveHistory();
  }

  function onNative(e) {
    const t = e.id ? tab(e.id) : null;
    switch (e.type) {
      case 'state': {
        if (!t) return;
        if (e.url && e.url !== t.url) t.popupNoticed = false;
        if (e.url) t.url = e.url;
        if (e.title && !/^file:/.test(e.title)) t.title = e.title;
        t.loading = !!e.loading;
        t.back = !!e.back;
        t.fwd = !!e.fwd;
        t.secure = !!e.secure;
        t.desktop = !!e.desktop;
        if (typeof e.blocked === 'number') t.blocked = e.blocked;
        if (!e.loading) t.progress = 100;
        if (e.url && !e.loading && !t.hidden) recordHistory(e.url, e.title);
        if (!e.loading && e.url && e.url !== 'about:blank') resolveLoadWaiters(t.id);
        if (t.id === activeId) renderBar();
        if (screen === 'tabs') queueRenderTabs();
        saveSession();
        break;
      }
      case 'progress':
        if (!t) return;
        t.progress = e.p;
        if (e.p < 100) t.loading = true;
        if (t.id === activeId) renderProgress();
        break;
      case 'icon': {
        const host = C.hostOf(e.url || '');
        if (!host || !e.data) return;
        if (favicons[host] !== e.data) {
          favicons[host] = e.data;
          const keys = Object.keys(favicons);
          if (keys.length > 400) delete favicons[keys[0]];
          saveFavicons();
        }
        break;
      }
      case 'thumb':
        if (t && e.data) {
          t.thumb = e.data;
          if (screen === 'tabs') queueRenderTabs();
        }
        break;
      case 'blocked': {
        if (t) t.blocked = e.total;
        const k = C.dayKey();
        stats.blocked[k] = (Number(stats.blocked[k]) || 0) + (e.add || 0);
        saveStats();
        if (t && t.id === activeId) renderBar();
        break;
      }
      case 'opened': {
        const opener = tab(e.opener);
        const nt = makeTab({ id: e.id, space: opener ? opener.space : space, home: false, live: true, opener: e.opener, url: '', loading: true });
        insertTab(nt, e.opener);
        activate(nt.id);
        update();
        break;
      }
      case 'closeTab':
        closeTab(e.id);
        break;
      case 'gone':
        if (!t) return;
        t.live = false;
        t.loading = false;
        if (t.id === activeId && !t.home) ensureLive(t, true);
        update();
        break;
      case 'back':
        goBack();
        break;
      case 'openUrl': {
        const url = C.resolveInput(e.url, settings.searchEngine);
        if (!url) return;
        closeScreen(true);
        closeSheet(true);
        if (screen === 'welcome') screen = null;
        const cur = activeTab();
        if (cur && cur.home && !cur.live) {
          cur.external = !!e.external;
          navigate(url);
        } else {
          openTab(url, { external: !!e.external });
        }
        break;
      }
      case 'find':
        if (!findOpen) return;
        $('#find-count').textContent = e.count ? e.index + '/' + e.count : $('#find-q').value ? '0/0' : '';
        break;
      case 'longpress':
        if (t && t.id === activeId) openLinkSheet(e);
        break;
      case 'keyboard':
        document.body.classList.toggle('kb', !!e.open);
        break;
      case 'bar':
        barAction(e);
        break;
      case 'barArea':
        // How much of the bottom of the screen the app's glass bar takes.
        document.documentElement.style.setProperty('--nb-cover', (Number(e.px) || 0) + 'px');
        break;
      case 'theme':
        dark = !!e.dark;
        applyTheme();
        applyReaderLook();
        lastModeSig = '';
        update();
        break;
      case 'pause':
        flushSaves();
        break;
      case 'resume':
        try {
          isDefaultBrowser = !!N.isDefault();
        } catch (err) {
          isDefaultBrowser = false;
        }
        if (pendingInstall && N.canInstall()) {
          pendingInstall = false;
          installUpdateNow();
        }
        if (Date.now() - (settings.lastUpdateCheck || 0) > 6 * 3600000) checkForUpdates(false);
        if (!$('#home').hidden) {
          renderHome();
          refreshWeather(false);
        }
        break;
      case 'trim':
        tabs.forEach((x) => {
          if (x.id !== activeId) sleepTab(x);
        });
        break;
      case 'download':
        toast('Downloading ' + e.name);
        break;
      case 'popupBlocked':
        if (t && t.id === activeId && !t.popupNoticed) {
          t.popupNoticed = true;
          const root = C.rootDomain(C.hostOf(t.url));
          barNotice({ icon: 'bgtab', text: 'Pop-up blocked', action: 'Allow on ' + (root.length > 16 ? 'this site' : root), ms: 6000, onAction: () => {
            if (!Array.isArray(settings.popupAllow)) settings.popupAllow = [];
            if (settings.popupAllow.indexOf(root) < 0) settings.popupAllow = settings.popupAllow.concat([root]);
            saveSettings();
            pushShield();
            toast('Pop-ups allowed on ' + root + '. Try the button again');
          } });
        }
        break;
      case 'tts':
        onTts(e);
        break;
      case 'voice':
        onVoice(e);
        break;
      case 'shot':
        onShot(e);
        break;
      case 'pip':
        document.body.classList.toggle('pip', !!e.on);
        if (e.on && sheet) {
          closeSheet(true);
          update();
        }
        break;
      case 'defaultBrowser':
        isDefaultBrowser = !!e.isDefault;
        if (isDefaultBrowser) toast('TP Browser is now your default browser 🎉');
        if (screen === 'settings') renderSettings();
        break;
      case 'fetch': {
        const req = pendingRequests.get(e.reqId);
        if (req) {
          pendingRequests.delete(e.reqId);
          clearTimeout(req.timer);
          req.resolve({ status: e.status || 0, body: e.body || '', error: e.error || '', retryAfter: e.retryAfter || '' });
          return;
        }
        const resolve = pendingFetches.get(e.reqId);
        if (!resolve) return;
        pendingFetches.delete(e.reqId);
        resolve(e.status >= 200 && e.status < 300 ? e.body : null);
        break;
      }
      case 'chunk': {
        const req = pendingRequests.get(e.reqId);
        if (req && req.onChunk) req.onChunk(e.data || '');
        break;
      }
      case 'eval': {
        const w = pendingEvals.get(e.reqId);
        if (!w) return;
        pendingEvals.delete(e.reqId);
        clearTimeout(w.timer);
        w.resolve(e.error ? { error: e.error } : { result: e.result });
        break;
      }
      case 'update':
        onUpdateEvent(e);
        break;
      case 'key':
        if (e.key === 'l') openSearch('', {});
        else if (e.key === 't') openTab('');
        else if (e.key === 'w' && activeId) closeTab(activeId);
        else if (e.key === 'f') openFind();
        else if (e.key === 'r' && pageTab()) N.nav(activeId, 'reload');
        break;
      default:
        break;
    }
  }

  window.TP = { onNative };

  // ------------------------------------------------------------------------------------------
  // Start
  // ------------------------------------------------------------------------------------------

  function restore() {
    const session = load('session', null);
    if (settings.restoreTabs && session && Array.isArray(session.tabs) && session.tabs.length) {
      tabs = session.tabs
        .filter((t) => t && t.id && spaceById(t.space))
        .map((t) => makeTab({ id: t.id, space: t.space, url: t.home ? '' : t.url || '', title: t.title || '', home: !!t.home || !t.url, desktop: !!t.desktop, fromHome: !!t.fromHome }));
      activeBySpace = session.activeBySpace || {};
      if (spaceById(session.space)) space = session.space;
    }
    if (!tabs.length) {
      tabs = [makeTab({ space })];
      activeBySpace = {};
    }
    let first = tab(activeBySpace[space]);
    if (!first || first.space !== space) first = tabsIn(space).slice(-1)[0] || tabs[0];
    space = first.space;
    applySpaceColors();
    activate(first.id);
  }

  function setupWelcome() {
    $('#w-name').value = settings.name && settings.name !== OLD_DEFAULT_NAME ? settings.name : '';
    $('#w-default').onclick = () => N.makeDefault();
    $('#w-default').hidden = !canDefault();
    $('#w-start').onclick = () => {
      settings.name = $('#w-name').value.trim();
      settings.nameConfirmed = true;
      settings.nameChecked = true;
      settings.onboarded = true;
      saveSettings();
      $('#w-name').blur();
      screen = null;
      update();
    };
  }

  function tick() {
    if (settings.focusEndsAt && settings.focusEndsAt <= Date.now()) endFocus(false);
    if (!$('#home').hidden) {
      renderClock();
      renderFocusCard();
    }
  }

  function sleepIdleTabs() {
    if (!settings.sleepAfter) return;
    const cutoff = Date.now() - settings.sleepAfter * 60000;
    tabs.forEach((t) => {
      if (t.live && t.id !== activeId && t.lastActive < cutoff) sleepTab(t);
    });
  }

  let ai = null;

  /**
   * Phones set up before 2.1.2 all started with the name "Tonpoon", so TP AI could treat everyone as
   * the same person. Ask each person for their own name (empty box, nothing pre-filled).
   */
  const OLD_DEFAULT_NAME = 'Tonpoon';

  function needsNameCheck() {
    return settings.onboarded && (!settings.nameConfirmed || (settings.name === OLD_DEFAULT_NAME && !settings.nameChecked));
  }

  function askName() {
    if (screen || sheet) return setTimeout(askName, 3000);
    const recheck = settings.name === OLD_DEFAULT_NAME;
    openSheet('name', (s) => {
      const input = el('input', { type: 'text', value: recheck ? '' : settings.name || '', maxlength: '30', placeholder: 'Type your name', autocomplete: 'off', style: 'width:100%;height:50px;padding:0 16px;border:0;border-radius:16px;background:var(--field);outline:none;font-size:17px' });
      const save = (name) => {
        const before = settings.name;
        settings.name = name;
        settings.nameConfirmed = true;
        settings.nameChecked = true;
        saveSettings();
        // A chat that called this person by someone else's name shouldn't carry on.
        if (before !== name && ai) ai.newChat();
        input.blur();
        closeSheet();
      };
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && input.value.trim()) save(input.value.trim());
      });
      s.append(el('div', { class: 'sheet-hero' },
