        el('p', { text: 'Type your own name. It shows on your home page and TP AI uses it to talk to you. It stays on this ' + deviceWord() + ', and your TP AI chats are only yours.' })));
      s.append(el('div', { style: 'padding:6px 24px 0' }, input));
      s.append(el('div', { class: 'sheet-actions' },
        el('button', { class: 'btn ghost', text: 'Skip', onclick: () => save(recheck ? '' : settings.name || '') }),
        el('button', { class: 'btn', text: 'Save', onclick: () => {
          if (!input.value.trim()) return input.focus();
          save(input.value.trim());
        } })));
    });
  }

  /** What the TP AI module can use. */
  function appApi() {
    return {
      N, C, el, icon, toast, haptic, settings, load, saveSoon,
      device: deviceWord(),
      saveSettings: () => saveSettings(),
      tabs: () => tabs.filter((t) => !t.hidden),
      tab,
      activeTab,
      pageTab,
      activeId: () => activeId,
      spaceById,
      ensureLive,
      waitForLoad,
      evalInTab,
      request: nativeRequest,
      openTab(url, opts) {
        opts = opts || {};
        if (!opts.keepScreen && !opts.background) {
          closeScreen(true);
          closeSheet(true);
        }
        return openTab(url, opts);
      },
      navigate,
      activate(id) {
        activate(id);
        update();
      },
      closeTab(id) {
        closeTab(id);
      },
      openScreen(id) {
        openScreen(id);
