      closeTab: log('closeTab'),
      showTab: log('showTab'),
      loadUrl: log('loadUrl'),
      nav: log('nav'),
      setUiMode: log('setUiMode'),
      find: log('find'),
      thumbnail: log('thumbnail'),
      setDesktop: log('setDesktop'),
      setShield: log('setShield'),
      setFocus: log('setFocus'),
      setTextZoom: log('setTextZoom'),
      fetch: (id, url) => {
        calls.push(['fetch', id, url]);
        const key = Object.keys(canned).find((k) => url.indexOf(k) >= 0);
        setTimeout(() => window.TP.onNative({ type: 'fetch', reqId: id, status: key ? 200 : 0, body: key ? canned[key] : '' }), 20);
      },
      share: log('share'),
      copy: log('copy'),
      toast: log('toast'),
      openExternal: log('openExternal'),
      openDownloads: log('openDownloads'),
      download: log('download'),
      minimize: log('minimize'),
      haptic: () => {},
      clearData: log('clearData'),
      makeDefault: log('makeDefault'),
      isDefault: () => false,
      info: () => JSON.stringify({ version: (window.TP_BUILD || {}).version || '2.1.0', versionCode: 20100, webview: '141.0.7390.122', android: '15', sdk: 35, canInstall: true, pip: true, voice: true }),
      request: (id, url, method, headers, body, stream) => {
        calls.push(['request', id, url, method, body]);
        const mock = window.__tpMockRequest;
        const reply = mock ? mock(url, method, headers, body, stream) : null;
        const send = (o) => window.TP.onNative(Object.assign({ reqId: id }, o));
