      evalInTab: (id, tabId, script) => {
        calls.push(['evalInTab', id, tabId, script.slice(0, 40)]);
        const mock = window.__tpMockEval;
        setTimeout(() => window.TP.onNative({ type: 'eval', reqId: id, result: mock ? mock(tabId, script) : 'null' }), 20);
      },
      downloadUpdate: log('downloadUpdate'),
      installUpdate: log('installUpdate'),
      canInstall: () => true,
      setPopupAllow: log('setPopupAllow'),
      pageReport: () => JSON.stringify({ version: '2.1.6', webview: '141.0', android: '15', host: 'play.blooket.com', errors: ['E Uncaught TypeError: x is not a function (app.js:12)'], popupsBlocked: 1, blocked: 0, desktop: false, shield: false }),
      allowInstalls: log('allowInstalls'),
      speak: (id, text, lang, rate, queue) => {
        calls.push(['speak', id, text.slice(0, 30), lang, rate, queue]);
        const q = (window.__tpSpeechQ = queue ? window.__tpSpeechQ || [] : []);
