        const next = () => {
          const cur = q.shift();
          if (!cur) return;
          window.TP.onNative({ type: 'tts', id: cur, state: 'start' });
          window.__tpSpeechTimer = setTimeout(() => {
            window.TP.onNative({ type: 'tts', id: cur, state: 'done' });
            next();
          }, window.__tpSpeechMs || 400);
        };
        if (!queue) setTimeout(next, 10);
      },
      stopSpeaking: () => {
        calls.push(['stopSpeaking']);
        clearTimeout(window.__tpSpeechTimer);
        window.__tpSpeechQ = [];
      },
      canVoice: () => true,
      voice: (target, lang) => {
        calls.push(['voice', target, lang]);
        if (window.__tpVoiceReply) setTimeout(() => window.TP.onNative({ type: 'voice', target, text: window.__tpVoiceReply }), 50);
      },
      setPip: log('setPip'),
      enterPip: log('enterPip'),
      videoState: () => window.__tpVideo || '',
      screenshot: (id) => {
        calls.push(['screenshot', id]);
        setTimeout(() => window.TP.onNative({ type: 'shot', ok: true, uri: 'content://media/external/images/media/1', thumb: '' }), 60);
      },
      shareImage: log('shareImage'),
      setDarkPages: log('setDarkPages'),
      showTabSlide: log('showTabSlide'),
      hapticKind: () => {},
    };
  }

  start();
})();

