        rain: d.daily && d.daily.precipitation_probability_max ? d.daily.precipitation_probability_max[0] : null,
      };
    } catch (e) {
      return null;
    }
  }

  function parseAir(body) {
    try {
      const d = JSON.parse(body);
      if (!d.current || d.current.us_aqi == null) return null;
      return { aqi: d.current.us_aqi, pm25: d.current.pm2_5, pm10: d.current.pm10 };
    } catch (e) {
      return null;
    }
  }

  function toF(c) {
    return c * 9 / 5 + 32;
  }

  const SPACE_COLORS = {
    violet: ['#7c5cff', '#4f8bff'],
    blue: ['#2f7bf6', '#06b6d4'],
    teal: ['#0ea5a4', '#22c55e'],
    green: ['#22c55e', '#a3e635'],
    orange: ['#f97316', '#facc15'],
    pink: ['#ec4899', '#a855f7'],
    red: ['#ef4444', '#f97316'],
    slate: ['#64748b', '#a1a1aa'],
  };

  // ------------------------------------------------------------------------------------------
  // Address-bar calculator: "12*7", "(3+4)/2", "2^10", "15%", "3 x 4", "10 ÷ 4"
  // ------------------------------------------------------------------------------------------

  /** The answer, or null when the text isn't a sum (dates and phone numbers aren't sums). */
  function calc(input) {
    let s = String(input == null ? '' : input).trim();
    if (!s || s.length > 100) return null;
    s = s.replace(/^=\s*/, '').replace(/[×xX]/g, '*').replace(/÷/g, '/').replace(/[−–]/g, '-').replace(/\*\*/g, '^').replace(/(\d),(?=\d{3}\b)/g, '$1');
    if (!/^[\d\s.+\-*/^%()]+$/.test(s) || !/\d/.test(s)) return null;
    if (!/\d\s*[+\-*/^%]/.test(s) && !/\)\s*[+\-*/^]/.test(s)) return null;
    if (/^\d+(-\d+){2,}$/.test(s.replace(/\s/g, '')) || /^\d{1,2}\/\d{1,2}\/\d{2,4}$/.test(s)) return null;
    let i = 0;
    const peek = () => {
      while (s[i] === ' ') i++;
      return s[i];
    };
    const fail = () => {
      throw new Error('bad');
    };
    function primary() {
      const c = peek();
      if (c === '(') {
        i++;
        const v = expr();
        if (peek() !== ')') fail();
        i++;
        return v;
      }
      const m = /^(\d+\.?\d*|\.\d+)/.exec(s.slice(i));
      if (!m) fail();
      i += m[0].length;
      return parseFloat(m[0]);
    }
    function postfix() {
      let v = primary();
      while (peek() === '%') {
        i++;
        v /= 100;
      }
      return v;
    }
    function unary() {
      const c = peek();
      if (c === '-') {
        i++;
        return -unary();
      }
      if (c === '+') {
        i++;
        return unary();
      }
      return power();
    }
    function power() {
      const base = postfix();
      if (peek() === '^') {
        i++;
        return Math.pow(base, unary());
      }
      return base;
    }
    function term() {
      let v = unary();
      for (;;) {
        const c = peek();
        if (c === '*') {
          i++;
          v *= unary();
        } else if (c === '/') {
          i++;
          v /= unary();
        } else return v;
      }
    }
    function expr() {
      let v = term();
      for (;;) {
        const c = peek();
        if (c === '+') {
          i++;
          v += term();
        } else if (c === '-') {
          i++;
          v -= term();
        } else return v;
      }
    }
    try {
      const v = expr();
      if (peek() !== undefined) return null;
      if (!isFinite(v)) return null;
      return Number(v.toPrecision(12));
    } catch (e) {
      return null;
    }
  }

  function fmtNumber(n) {
    if (Math.abs(n) >= 1e15 || (n !== 0 && Math.abs(n) < 1e-6)) return n.toExponential(6).replace(/\.?0+e/, 'e');
    return n.toLocaleString('en-US', { maximumFractionDigits: 10 });
  }

  /** Days in a row with some focus time. Today only breaks the streak once it's over. */
  function focusStreak(map, now) {
    const d = new Date(now == null ? Date.now() : now);
    const has = () => Number((map || {})[dayKey(d.getTime())]) > 0;
    if (!has()) d.setDate(d.getDate() - 1);
    let n = 0;
    while (has() && n < 1000) {
      n++;
      d.setDate(d.getDate() - 1);
    }
    return n;
  }

  // ------------------------------------------------------------------------------------------
  // Translate pages (Google Translate's page proxy) and read-aloud helpers
  // ------------------------------------------------------------------------------------------

  function translateUrl(url, lang) {
    const original = untranslateUrl(url) || url;
    return 'https://translate.google.com/translate?sl=auto&tl=' + encodeURIComponent(lang) + '&hl=' + encodeURIComponent(lang) + '&u=' + encodeURIComponent(original);
  }

  /** "https://www-bbc-com.translate.goog/news?_x_tr_sl=auto" -> "https://www.bbc.com/news". Null if not translated. */
  function untranslateUrl(url) {
    const u = parseUrl(url);
    if (!u) return null;
    const m = /^(.+)\.translate\.goog$/i.exec(u.hostname);
    if (!m) return null;
    const host = m[1].split('--').map((p) => p.replace(/-/g, '.')).join('-');
    const params = new URLSearchParams(u.search);
    Array.from(params.keys()).filter((k) => /^_x_tr_/.test(k)).forEach((k) => params.delete(k));
    const q = params.toString();
    return 'https://' + host + u.pathname + (q ? '?' + q : '') + u.hash;
  }

  /** "th" for Thai text, else the page's language, else "". */
  function speechLang(text, pageLang) {
    const t = String(text || '');
    const thai = (t.match(/[฀-๿]/g) || []).length;
    const letters = (t.match(/[A-Za-zÀ-ɏ฀-๿]/g) || []).length;
    if (thai && thai / Math.max(1, letters) > 0.3) return 'th';
    const p = String(pageLang || '').toLowerCase().split(/[-_]/)[0];
    if (p === 'th' && !thai) return 'en';
    // Plain English letters with no language given: an English voice, even on a phone set to Thai.
    const latin = (t.match(/[A-Za-z]/g) || []).length;
    if (!p && latin && latin / Math.max(1, letters) > 0.8) return 'en';
    return p;
  }

  /** Splits long text at sentence ends (or spaces) so each piece can be read aloud. */
  function splitSpeech(text, max) {
    max = max || 1200;
    const out = [];
    let rest = String(text || '').replace(/\s+/g, ' ').trim();
    while (rest.length > max) {
      const head = rest.slice(0, max);
      let cut = -1;
      const re = /[.!?。！？](?=\s)|\s{1}/g;
      let m;
      let lastSentence = -1;
      let lastSpace = -1;
      while ((m = re.exec(head))) {
        if (m[0] === ' ') lastSpace = m.index;
        else lastSentence = m.index + 1;
      }
      cut = lastSentence > max * 0.4 ? lastSentence : lastSpace > 0 ? lastSpace : max;
      out.push(rest.slice(0, cut).trim());
      rest = rest.slice(cut).trim();
    }
    if (rest) out.push(rest);
    return out;
  }

  /** Rough minutes to read: Thai has no spaces, so it counts characters instead of words. */
  function readingMinutes(text) {
    const t = String(text || '');
    const thai = (t.match(/[฀-๿]/g) || []).length;
    const words = (t.replace(/[฀-๿]/g, ' ').match(/\S+/g) || []).length;
    return Math.max(1, Math.round((words + thai / 6) / 220));
  }

  /** Markdown answer -> plain text for reading aloud. */
  function plainText(md) {
    return String(md || '')
      .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '$1')
      .replace(/https?:\/\/\S+/g, '')
      .replace(/[*_`#>]+/g, '')
      .replace(/^\s*([-•]|\d+[.)])\s+/gm, '')
      .replace(/\n{2,}/g, '\n')
      .trim();
  }

  const api = {
    SEARCH_ENGINES, SPACE_COLORS, engine, searchUrl, suggestUrl, parseSuggest, looksLikeUrl, resolveInput, realUrl, isTpPage,
    hostOf, rootDomain, displayUrl, normalizeSite, hostInList, dayKey, sumLastDays, pruneDays, fmtCount, clockText, greeting,
    minutesText, rankEntries, inlineCompletion, groupByDay, weatherInfo, aqiLevel, weatherUrl, airUrl, geocodeUrl, parseWeather,
    parseAir, toF, calc, fmtNumber, focusStreak, translateUrl, untranslateUrl, speechLang, splitSpeech, readingMinutes, plainText,
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else global.TPCore = api;
})(typeof window !== 'undefined' ? window : globalThis);

files.ui/glass.css:
/* TP Browser for iPhone and iPad: Liquid Glass.
 *
 * Buttons, the address bar, menus and sheets become see-through glass: content behind them is blurred
 * and brightened, edges catch the light, and they lift and glow where you touch them. Selections sit on
 * a glass "lens" that slides between choices. Everything here is scoped to html.ios, so TP Browser for
 * Android (which shares this interface) looks exactly as before.
 *
 * html.ios-edge: the app lets TP's interface reach the bottom edge of the screen (app build 2+), so the
 * address bar and sheets can float above the home indicator. */

html.ios {
  --lg-fill: rgba(255, 255, 255, 0.4);
  --lg-fill-hi: rgba(255, 255, 255, 0.66);
  --lg-thick: rgba(249, 249, 252, 0.78);
  --lg-field: rgba(120, 120, 128, 0.12);
  --lg-blur: saturate(185%) blur(18px);
  --lg-blur-thick: saturate(190%) blur(36px);
  --lg-sheen: linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0.14) 36%, rgba(255, 255, 255, 0) 56%, rgba(255, 255, 255, 0.12) 100%);
  --lg-rim: inset 0 1px 0.5px rgba(255, 255, 255, 0.95), inset 0 -0.5px 0.5px rgba(255, 255, 255, 0.55), inset 0 0 0 0.5px rgba(255, 255, 255, 0.6), inset 0 -10px 18px -12px rgba(255, 255, 255, 0.5);
  --lg-edge: 0 0 0 0.5px rgba(30, 30, 60, 0.07);
  --lg-lift: 0 1px 3px rgba(20, 20, 50, 0.06), 0 10px 28px rgba(20, 20, 50, 0.13);
  --lg-press: rgba(255, 255, 255, 0.55);
  --lg-glow: rgba(255, 255, 255, 0.85);
  --lg-lens: rgba(255, 255, 255, 0.94);
  --lg-green: #34c759;
  --lg-bar: rgba(255, 255, 255, 0.8);
  --ios-safe-bottom: 0px;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'SF Pro', 'Helvetica Neue', 'Sukhumvit Set', system-ui, sans-serif;
}

html.ios.ios-edge {
  --ios-safe-bottom: env(safe-area-inset-bottom, 0px);
}

html.ios.dark {
  --lg-fill: rgba(64, 64, 76, 0.36);
  --lg-fill-hi: rgba(96, 96, 110, 0.52);
  --lg-thick: rgba(30, 30, 36, 0.8);
  --lg-field: rgba(118, 118, 128, 0.24);
  --lg-sheen: linear-gradient(180deg, rgba(255, 255, 255, 0.17) 0%, rgba(255, 255, 255, 0.04) 36%, rgba(255, 255, 255, 0) 56%, rgba(255, 255, 255, 0.05) 100%);
  --lg-rim: inset 0 1px 0.5px rgba(255, 255, 255, 0.34), inset 0 -0.5px 0.5px rgba(255, 255, 255, 0.12), inset 0 0 0 0.5px rgba(255, 255, 255, 0.17), inset 0 -10px 18px -12px rgba(255, 255, 255, 0.14);
  --lg-edge: 0 0 0 0.5px rgba(0, 0, 0, 0.45);
  --lg-lift: 0 1px 3px rgba(0, 0, 0, 0.35), 0 12px 32px rgba(0, 0, 0, 0.45);
  --lg-press: rgba(255, 255, 255, 0.16);
  --lg-glow: rgba(255, 255, 255, 0.4);
  --lg-lens: rgba(108, 108, 118, 0.92);
  --lg-green: #30d158;
  --lg-bar: rgba(38, 38, 44, 0.8);
}

/* Over the colourful wallpapers the glass is clearer and the text white. */
html.ios body.vivid #home {
  --lg-fill: rgba(255, 255, 255, 0.16);
  --lg-fill-hi: rgba(255, 255, 255, 0.3);
  --lg-sheen: linear-gradient(180deg, rgba(255, 255, 255, 0.3) 0%, rgba(255, 255, 255, 0.06) 36%, rgba(255, 255, 255, 0) 56%, rgba(255, 255, 255, 0.08) 100%);
  --lg-rim: inset 0 1px 0.5px rgba(255, 255, 255, 0.6), inset 0 -0.5px 0.5px rgba(255, 255, 255, 0.22), inset 0 0 0 0.5px rgba(255, 255, 255, 0.3), inset 0 -10px 18px -12px rgba(255, 255, 255, 0.25);
  --lg-lift: 0 1px 3px rgba(0, 0, 0, 0.15), 0 12px 30px rgba(0, 0, 0, 0.22);
  --lg-press: rgba(255, 255, 255, 0.24);
}

/* ---------- The material ---------- */

html.ios :is(.glass, .chip, .home-search, .card, .current-page, .space-chip, .ai-chip, .quick button, .search-field,
             .page-top .icon-btn, .tabs-top .icon-btn, .reader-top .icon-btn, .rs-btn, #bar-notice, #findbar, #mainbar, .btn.ghost) {
  background: var(--lg-sheen), var(--lg-fill);
  -webkit-backdrop-filter: var(--lg-blur);
  backdrop-filter: var(--lg-blur);
  box-shadow: var(--lg-rim), var(--lg-edge), var(--lg-lift);
}

/* Over a website the bar only has the page's own colour behind it (the app draws that), so it's frostier:
   icons stay readable whether the page is light or dark. On the home page it's clear glass over the home. */
html.ios :is(#mainbar, #bar-notice, #findbar) {
  background: var(--lg-sheen), var(--lg-bar);
}

html.ios body.on-home #mainbar {
  background: var(--lg-sheen), var(--lg-fill);
}

/* Thick glass for panels with lots of text: sheets, TP AI, settings groups, tab cards. */
html.ios :is(.sheet, .ai-panel, .set-card, .tab-card, .reader-player) {
  background: var(--lg-sheen), var(--lg-thick);
  -webkit-backdrop-filter: var(--lg-blur-thick);
  backdrop-filter: var(--lg-blur-thick);
  box-shadow: var(--lg-rim), var(--lg-edge), 0 18px 50px rgba(10, 10, 40, 0.2);
}

/* Tinted glass for the main actions. */
html.ios :is(.btn:not(.ghost), .fab, .home-ai, .ai-send:not(.stop):not(.mic), .update-banner) {
  background: var(--lg-sheen), linear-gradient(135deg, color-mix(in oklab, var(--c1) 84%, transparent), color-mix(in oklab, var(--c1) 50%, color-mix(in oklab, var(--c2) 76%, transparent)));
  -webkit-backdrop-filter: var(--lg-blur);
  backdrop-filter: var(--lg-blur);
  box-shadow: inset 0 1px 0.5px rgba(255, 255, 255, 0.7), inset 0 -0.5px 0.5px rgba(255, 255, 255, 0.3), inset 0 0 0 0.5px rgba(255, 255, 255, 0.35),
    inset 0 -10px 18px -12px rgba(255, 255, 255, 0.45), 0 8px 22px color-mix(in oklab, var(--c1) 34%, transparent);
  color: #fff;
}

html.ios .btn.ghost {
  color: var(--accent);
}

/* ---------- Touch: glass lifts and lights up where you press ---------- */

html.ios :is(.btn, .icon-btn, .chip, .fab, .home-ai, .home-search, .ai-chip, .space-chip, .quick button, .ai-send, .rs-btn, #pill-text, #pill-shield, #pill-reload, .tab-card) {
  transition: transform 0.55s var(--spring-pop), background-color 0.2s ease, box-shadow 0.25s ease, opacity 0.2s ease;
}

/* :where() keeps this weaker than the .lg-down swell below (it only cancels the Android shrink-on-press). */
html.ios :where(.btn, .icon-btn, .tile, .ai-chip, .chip, .fab, .home-ai, .home-search, .space-chip, .quick button):active,
html.ios :where(.sheet-item, .set-row, .row):active {
  transform: none;
}

html.ios :is(.btn, .chip, .fab, .home-ai, .ai-chip, .space-chip, .quick button, .ai-send, .rs-btn, .icon-btn).lg-down {
  transform: scale(1.07);
  transition: transform 0.28s var(--spring-pop), background-color 0.1s ease, box-shadow 0.15s ease;
}

html.ios .home-search.lg-down,
html.ios .tab-card.lg-down {
  transform: scale(1.025);
  transition: transform 0.28s var(--spring-pop);
}

/* Plain toolbar buttons get a glass lens only while pressed. */
html.ios .icon-btn:not(.glass).lg-down {
  background: var(--lg-sheen), var(--lg-press);
  box-shadow: var(--lg-rim), var(--lg-edge);
}

html.ios :is(.btn, .icon-btn, .chip, .fab, .home-ai, .home-search, .ai-chip, .space-chip, .quick button, .ai-send, .rs-btn, .sheet-item, .set-row, .sugg, .row, .check-row, .lang, .rs-theme, #pill-text) {
  position: relative;
  overflow: hidden;
  isolation: isolate;
}

html.ios .lg-glow {
  position: absolute;
  z-index: -1;
  width: 180px;
  height: 180px;
  margin: -90px 0 0 -90px;
  border-radius: 50%;
  background: radial-gradient(closest-side, var(--lg-glow), transparent);
  opacity: 0;
  transform: scale(0.3);
  pointer-events: none;
  animation: lgGlowIn 0.45s var(--spring-soft) forwards;
}

html.ios .lg-glow.out {
  animation: lgGlowOut 0.5s ease forwards;
}

@keyframes lgGlowIn {
  to {
    opacity: 0.55;
    transform: scale(1);
  }
}

@keyframes lgGlowOut {
  from {
    opacity: 0.55;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(1.35);
  }
}

/* Rows in menus and lists light up as a glass capsule. */
html.ios .sheet-item {
  width: calc(100% - 16px);
  margin: 0 8px;
  padding: 0 14px;
  border-radius: 18px;
}

html.ios :is(.sheet-item, button.set-row, .sugg, .row, .check-row, .lang):active,
html.ios :is(.sheet-item, button.set-row, .sugg, .row, .check-row, .lang).lg-down {
  background: var(--lg-press);
  box-shadow: var(--lg-rim);
}

html.ios .ripple {
  display: none;
}

/* ---------- The floating address bar ---------- */

html.ios #bar {
  background: transparent;
  box-shadow: none !important;
  padding-bottom: var(--ios-safe-bottom);
}

html.ios #mainbar {
  height: 54px;
  margin: 5px 10px;
  padding: 0 5px;
  gap: 0;
  border-radius: 27px;
}

html.ios #mainbar .icon-btn {
  width: 42px;
  height: 44px;
  border-radius: 22px;
}

html.ios #pill {
  height: 42px;
  margin: 0 3px;
  border-radius: 21px;
  background: var(--lg-field);
  box-shadow: inset 0 0.5px 1px rgba(0, 0, 0, 0.06);
}

html.ios.dark #pill {
  box-shadow: inset 0 0.5px 1px rgba(0, 0, 0, 0.3);
}

html.ios #pill-shield {
  border-radius: 21px 0 0 21px;
}

html.ios #progress {
  top: 3px;
  left: 30px;
  right: 30px;
  height: 2.5px;
  border-radius: 2px;
}

html.ios #findbar {
  margin: 5px 10px;
  border-radius: 27px;
  padding: 0 6px 0 12px;
}

html.ios #bar-notice {
  margin: 0 12px 6px;
  border-radius: 22px;
}

/* ---------- Sheets and TP AI float above the bottom edge ---------- */

html.ios #backdrop {
  background: rgba(8, 8, 20, 0.22);
}

html.ios .sheet {
  border-radius: 30px 30px 0 0;
}

html.ios.ios-edge .sheet {
  left: 8px;
  right: 8px;
  bottom: calc(8px + var(--ios-safe-bottom) * 0.25);
  max-height: calc(88% - var(--ios-safe-bottom));
  border-radius: 34px;
  padding-bottom: 10px;
}

html.ios .sheet::before {
  width: 38px;
  height: 5px;
  border-radius: 3px;
  background: rgba(120, 120, 128, 0.35);
}

html.ios.ios-edge .ai-panel {
  margin: 0 8px calc(8px + var(--ios-safe-bottom) * 0.25);
  border-radius: 34px;
}

html.ios .ai-panel {
  border-radius: 30px 30px 0 0;
}

html.ios .ai-scrim {
  background: rgba(8, 8, 20, 0.22);
}

html.ios #ai-q,
html.ios .ai-form textarea {
  background: var(--lg-field);
}

/* ---------- Screens reach the bottom edge: keep their content above the home indicator ---------- */

html.ios.ios-edge #home {
  padding-bottom: calc(var(--bar-h) + 24px + var(--ios-safe-bottom));
}

html.ios.ios-edge .screen.page {
  padding-bottom: calc(40px + var(--ios-safe-bottom));
}

html.ios.ios-edge #search,
html.ios.ios-edge #tabs {
  padding-bottom: var(--ios-safe-bottom);
}

html.ios .page-top {
  background: color-mix(in oklab, var(--bg) 80%, transparent);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  backdrop-filter: saturate(180%) blur(20px);
}

html.ios :is(.page-top, .tabs-top, .reader-top) .icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 20px;
}

/* ---------- Home ---------- */

html.ios .home-search {
  height: 54px;
  border-radius: 27px;
}

html.ios body.vivid .home-search {
  color: rgba(255, 255, 255, 0.82);
}

html.ios body.vivid .hs-icon {
  color: #fff;
}

html.ios .card {
  border-radius: 24px;
}

html.ios .home-ai {
  border-radius: 27px;
}

/* ---------- Tabs ---------- */

html.ios .tab-card {
  border-radius: 22px;
}

html.ios .tab-card.active {
  box-shadow: var(--lg-rim), 0 0 0 2.5px color-mix(in oklab, var(--c1) 80%, transparent), 0 10px 30px color-mix(in oklab, var(--c1) 30%, transparent);
}

html.ios .space-chips {
  background: transparent;
  box-shadow: none;
}

html.ios .fab {
  border-radius: 28px;
}

/* ---------- Settings ---------- */

html.ios .set-card {
  border-radius: 26px;
}

/* iOS switch: green when on, and the knob turns into glass while you press it. */
html.ios .switch {
  width: 58px;
  height: 30px;
  border-radius: 15px;
  background: rgba(120, 120, 128, 0.22);
  box-shadow: inset 0 0 0 0.5px rgba(0, 0, 0, 0.04);
  transition: background 0.3s ease;
}

html.ios.dark .switch {
  background: rgba(120, 120, 128, 0.36);
}

html.ios .switch.on {
  background: var(--lg-green);
}

html.ios .switch::after {
  top: 2px;
  left: 2px;
  width: 34px;
  height: 26px;
  border-radius: 13px;
  background: #fff;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.16), 0 0 0 0.5px rgba(0, 0, 0, 0.04);
  transition: transform 0.55s var(--spring-pop), background-color 0.2s ease, box-shadow 0.2s ease;
}

html.ios .switch.on::after {
  transform: translateX(20px);
}

html.ios .lg-down .switch::after {
  background: rgba(255, 255, 255, 0.4);
  box-shadow: var(--lg-rim), 0 4px 14px rgba(0, 0, 0, 0.2);
  transform: scale(1.2, 1.15);
}

html.ios .lg-down .switch.on::after {
  transform: translateX(20px) scale(1.2, 1.15);
}

/* Segmented choices: a glass track, and a lens that slides to the one you pick. */
html.ios .seg {
  position: relative;
  gap: 2px;
  padding: 3px;
  border-radius: 22px;
  background: var(--lg-field);
}

html.ios .seg button {
  position: relative;
  z-index: 1;
  height: 36px;
  padding: 0 14px;
  border-radius: 18px;
  background: transparent;
  color: var(--text);
  font-weight: 600;
  transition: color 0.2s ease, transform 0.4s var(--spring-pop);
}

html.ios .seg button.on {
  background: transparent;
  color: var(--text);
  font-weight: 700;
}

html.ios .seg:not(.lg-ready) button.on {
  background: var(--lg-lens);
}

html.ios .lg-lens {
  position: absolute;
  z-index: 0;
  left: 0;
  top: 0;
  border-radius: 18px;
  background: var(--lg-sheen), var(--lg-lens);
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.12), var(--lg-rim), 0 0 0 0.5px rgba(0, 0, 0, 0.04);
  pointer-events: none;
  transition: translate 0.55s var(--spring-sheet), width 0.55s var(--spring-sheet), height 0.55s var(--spring-sheet), opacity 0.2s ease;
}

html.ios .lg-lens.moving {
  animation: lgLens 0.55s var(--spring-soft);
}

@keyframes lgLens {
  35% {
    scale: 1.14 0.86;
    background: var(--lg-sheen), var(--lg-fill-hi);
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.16), var(--lg-rim);
  }
}

/* Other selections (space chips, choices, reader themes) sit on raised glass. */
html.ios :is(.space-chip.on, .check-row.on, .lang.on, .sugg.sel) {
  background: var(--lg-sheen), var(--lg-fill-hi);
  box-shadow: var(--lg-rim), 0 0 0 1.5px color-mix(in oklab, var(--c1) 55%, transparent), var(--lg-lift);
}

html.ios .space-chip.on {
  color: var(--text);
}

html.ios .rs-theme.on .rs-swatch {
  box-shadow: var(--lg-rim), 0 0 0 3px var(--sheet), 0 0 0 5px var(--c1);
}

@media (prefers-reduced-motion: reduce) {
  html.ios .lg-glow,
  html.ios .lg-lens.moving {
    animation: none !important;
  }
}

/* ---------- iOS 26+: the address bar is Apple's real Liquid Glass, drawn by the app ---------- */
/* (html.ios-native-bar) This page keeps only notices and the find bar; the app puts its glass bar at the
   bottom and says how much room it takes (--nb-cover). */

html.ios-native-bar #mainbar,
html.ios-native-bar #progress {
  display: none !important;
}

html.ios.ios-native-bar body.full:not(.no-bar) #bar {
  padding-bottom: max(var(--ios-safe-bottom), var(--nb-cover, 0px));
}

html.ios.ios-native-bar #home {
  padding-bottom: calc(var(--nb-cover, 80px) + 20px);
}

html.ios.ios-native-bar #bar-notice {
  margin-bottom: 8px;
}

