'use strict';
/* TP Browser reader view: finds the article on a page (title, text, pictures) and leaves out menus,
 * ads, comments and "related" boxes. extract() runs inside the website's tab, so it must not use
 * anything from outside its own body. */
(function (global) {
  function extract() {
    try {
      var BAD = /(^|[\s_-])(comments?|share|sharing|social|related|promo|advert\w*|ads?|sponsor\w*|footer|nav|navbar|menu|subscribe|newsletter|cookie\w*|banner|popup|modal|sidebar|widget|breadcrumbs?|toolbar|signup|login|recommend\w*|outbrain|taboola|disqus|paywall|masthead)([\s_-]|$)/i;
      var GOOD = /article|content|main|post|story|entry|body|text/i;
      var SKIP = { NAV: 1, ASIDE: 1, FOOTER: 1, FORM: 1, BUTTON: 1, SCRIPT: 1, STYLE: 1, NOSCRIPT: 1, SVG: 1, IFRAME: 1, SELECT: 1, INPUT: 1, TEXTAREA: 1, DIALOG: 1, TEMPLATE: 1, CANVAS: 1, VIDEO: 1, AUDIO: 1 };
      var INLINE = /^(A|B|I|EM|STRONG|SPAN|BR|SMALL|SUP|SUB|CODE|MARK|U|ABBR|TIME|Q|S|CITE|FONT|WBR|DFN|KBD|VAR|DEL|INS)$/;

      var text = function (el) {
        return (el.innerText || el.textContent || '').replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
      };
      var oneLine = function (s) {
        return s.replace(/\s+/g, ' ').trim();
      };
      var hidden = function (el) {
        if (!el.getClientRects().length) return true;
        var cs = getComputedStyle(el);
        return cs.visibility === 'hidden' || cs.display === 'none' || cs.opacity === '0';
      };
      var bad = function (el) {
        var name = (el.id || '') + ' ' + (typeof el.className === 'string' ? el.className : '') + ' ' + (el.getAttribute('role') || '') + ' ' + (el.getAttribute('aria-label') || '');
        if (/^(navigation|banner|contentinfo|complementary|dialog|alert)$/.test(el.getAttribute('role') || '')) return true;
        return BAD.test(name) && !GOOD.test(el.id || '') && el.tagName !== 'ARTICLE' && el.tagName !== 'MAIN';
      };
      var linkDensity = function (el) {
        var total = text(el).length || 1;
        var links = 0;
        var as = el.querySelectorAll('a');
        for (var i = 0; i < as.length; i++) links += (as[i].innerText || '').length;
        return links / total;
      };

      // 1. The element that holds the most real paragraph text wins.
      var scores = new Map();
      var paras = document.querySelectorAll('p, pre, blockquote, li');
      for (var i = 0; i < paras.length && i < 3000; i++) {
        var p = paras[i];
        var t = p.innerText || '';
        if (t.length < 40) continue;
        var score = 1 + Math.min(3, Math.floor(t.length / 100)) + (t.split(/[,،、，]/).length - 1) * 0.25;
        var parent = p.parentElement;
        var grand = parent && parent.parentElement;
        if (parent) scores.set(parent, (scores.get(parent) || 0) + score);
        if (grand) scores.set(grand, (scores.get(grand) || 0) + score / 2);
      }
      var best = null;
      var bestScore = 0;
      scores.forEach(function (s, el) {
        if (el === document.documentElement) return;
        var adj = s * (1 - Math.min(0.9, linkDensity(el)));
        if (el.tagName === 'ARTICLE' || el.tagName === 'MAIN' || el.getAttribute('itemprop') === 'articleBody') adj *= 1.3;
        if (bad(el)) adj *= 0.3;
        if (adj > bestScore) {
          bestScore = adj;
          best = el;
        }
      });
      if (!best) best = document.querySelector('article') || document.querySelector('main,[role=main]') || document.body;
      // An <article> that contains the winner usually holds its heading and pictures too.
      var art = best.closest ? best.closest('article') : null;
      if (art && text(art).length < text(best).length * 1.6) best = art;

      // 2. Walk the article in order and keep headings, paragraphs, lists, quotes and pictures.
      var blocks = [];
      var seen = {};
      var chars = 0;
      var img = function (im) {
        var src = im.currentSrc || im.src || '';
        // Pictures that load later ("lazy") keep their real address in a data- attribute.
        if (!/^https:/.test(src)) src = im.getAttribute('data-src') || im.getAttribute('data-lazy-src') || im.getAttribute('data-original') || '';
        if (!/^https:/.test(src) || seen[src]) return;
        var w = im.naturalWidth || parseInt(im.getAttribute('width') || '0', 10) || (im.complete ? 0 : im.width) || 0;
        if (w && w < 160) return;
        seen[src] = 1;
        blocks.push({ t: 'img', src: src, alt: oneLine(im.alt || '').slice(0, 200) });
      };
      var onlyInline = function (el) {
        for (var k = el.firstElementChild; k; k = k.nextElementSibling) if (!INLINE.test(k.tagName)) return false;
        return true;
      };
      var addText = function (type, el, extra) {
        var x = type === 'pre' ? text(el) : oneLine(text(el));
        if (!x) return;
        var b = { t: type, x: x.slice(0, 6000) };
        if (extra) for (var key in extra) b[key] = extra[key];
        blocks.push(b);
        chars += x.length;
      };
