        if (depth > 30) return;
        for (var c = el.firstElementChild; c; c = c.nextElementSibling) {
          var tag = c.tagName;
          if (SKIP[tag] || bad(c) || hidden(c)) continue;
          if (/^H[1-6]$/.test(tag)) {
            var h = oneLine(text(c));
            if (h && h.length < 220) blocks.push({ t: 'h', x: h, l: Number(tag[1]) });
            continue;
          }
          if (tag === 'P') {
            if (linkDensity(c) < 0.6) addText('p', c);
            var ims = c.querySelectorAll('img');
            for (var a = 0; a < ims.length; a++) img(ims[a]);
            continue;
          }
          if (tag === 'BLOCKQUOTE') {
            addText('q', c);
            continue;
          }
          if (tag === 'PRE') {
            addText('pre', c);
            continue;
          }
