  font-size: 16px;
}

/* Message over the address bar (screenshot saved, pop-up blocked…). */
.bar-notice {
  position: absolute;
  left: 8px;
  right: 8px;
  top: 8px;
  height: calc(var(--bar-h) - 16px);
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 6px 0 8px;
  border-radius: 16px;
  background: color-mix(in oklab, var(--text) 94%, var(--c1));
  color: var(--bg);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22);
}

.bar-notice.in {
  animation: noticeIn 0.5s var(--spring-sheet) both;
}

.bar-notice.out {
  animation: noticeOut 0.22s var(--ease-in) both;
}

@keyframes noticeIn {
  from {
    opacity: 0;
    transform: translate3d(0, 70px, 0) scale(0.96);
  }
}

@keyframes noticeOut {
  to {
    opacity: 0;
    transform: translate3d(0, 50px, 0) scale(0.98);
  }
}

#bar-notice.in ~ #mainbar {
  opacity: 0.2;
  transition: opacity 0.2s ease;
}

#mainbar {
  transition: opacity 0.25s ease;
}

#bn-thumb {
  width: 30px;
  height: 36px;
  flex: none;
  border-radius: 6px;
  object-fit: cover;
  object-position: top;
  box-shadow: 0 0 0 1.5px color-mix(in oklab, var(--bg) 40%, transparent);
}

.bn-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  margin-left: 2px;
  opacity: 0.85;
}

.bn-icon svg {
  width: 20px;
  height: 20px;
}

.bn-text {
  flex: 1;
  min-width: 0;
  padding-left: 4px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bn-action {
  height: 36px;
  padding: 0 14px;
  flex: none;
  border-radius: 18px;
  color: color-mix(in oklab, var(--c1) 55%, var(--bg));
  font-weight: 800;
  font-size: 14px;
}

.bn-action:active {
  background: color-mix(in oklab, var(--bg) 14%, transparent);
}

/* Translate */
.lang-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 12px 16px 0;
}

.lang {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 54px;
  padding: 0 12px;
  border-radius: 16px;
  background: var(--field);
  font-weight: 600;
  text-align: left;
}

.lang.on {
  box-shadow: inset 0 0 0 2px var(--c1);
  background: var(--accent-soft);
}

.lang-badge {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex: none;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--c1), var(--c2));
  color: #fff;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.sheet-fine {
  margin: 14px 24px 2px;
  font-size: 12.5px;
  color: var(--faint);
  text-align: center;
}

/* QR code */
.qr-wrap {
  display: flex;
  justify-content: center;
  padding: 2px 24px 4px;
}

.qr-card {
  width: min(290px, 100%);
  padding: 16px 16px 14px;
  border-radius: 26px;
  background: #fff;
  color: #1d1b26;
  text-align: center;
  box-shadow: 0 1px 2px rgba(25, 20, 60, 0.08), 0 12px 32px rgba(25, 20, 60, 0.14);
}

.qr-card svg {
  display: block;
  width: 100%;
  height: auto;
}

.qr-title {
  margin-top: 8px;
  font-weight: 700;
  font-size: 15px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.qr-url {
  font-size: 12.5px;
  color: #6b6878;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sheet-qr.anim-in .qr-wrap {
  animation: popIn 0.7s var(--spring-bounce) both;
  animation-delay: 0.06s;
}

@keyframes popIn {
  from {
    opacity: 0;
    transform: scale(0.82);
  }
}

/* TP AI: voice, listen, a drag handle and livelier messages */
.ai-handle {
  width: 36px;
  height: 4px;
  margin: 8px auto -2px;
  border-radius: 2px;
  background: var(--line);
  flex: none;
}

.ai-msg.user .said {
  display: inline-grid;
  vertical-align: -3px;
  margin-right: 6px;
  opacity: 0.85;
}

.ai-msg.user .said svg {
  width: 15px;
  height: 15px;
}

.ai-send.mic {
  background: var(--accent-soft);
  color: var(--accent);
}

.mini.on {
  color: var(--accent);
  background: var(--accent-soft);
}

.ai-msg.enter,
.ai-step.enter {
  animation: msgIn 0.48s var(--spring-soft) both;
}

.ai-msg.user.enter {
