/* ---------------- Reader view ---------------- */

.reader {
  --r-bg: #fbfaf7;
  --r-text: #1f1d1a;
  --r-dim: rgba(31, 29, 26, 0.58);
  --r-line: rgba(31, 29, 26, 0.1);
