  --r-mark: rgba(255, 205, 80, 0.38);
  background: var(--r-bg);
  color: var(--r-text);
}

.reader.rt-sepia {
  --r-bg: #f4ecd8;
  --r-text: #3b2f22;
  --r-dim: rgba(59, 47, 34, 0.6);
  --r-line: rgba(59, 47, 34, 0.13);
  --r-mark: rgba(214, 150, 50, 0.3);
}

.reader.rt-dark {
  --r-bg: #17161c;
  --r-text: #e8e6ef;
  --r-dim: rgba(232, 230, 239, 0.58);
  --r-line: rgba(255, 255, 255, 0.09);
