  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  z-index: 3;
  pointer-events: none;
}

.reader-progress i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--c1), var(--c2));
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}

.reader-top {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 2px;
  height: 58px;
  padding: 0 4px;
  background: var(--r-bg);
  box-shadow: 0 1px 0 var(--r-line);
  transition: transform 0.42s var(--spring-soft);
}

.reader.hide-top .reader-top {
  transform: translate3d(0, -100%, 0);
}

.reader-top .icon-btn {
  color: var(--r-text);
}

.reader-site {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--r-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}

.reader-body {
