  padding: 16px 16px 6px;
}

.rs-theme {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 6px 0;
  border-radius: 16px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--dim);
