'use strict';
(function () {
  const params = new URLSearchParams(location.search);
  const url = params.get('u') || '';
  const desc = params.get('d') || '';
  const code = Number(params.get('c') || 0);
  let host = url;
  try {
    host = new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    // keep the raw text
  }
  const $ = (id) => document.getElementById(id);
  const offline = /INTERNET_DISCONNECTED|NETWORK_CHANGED/i.test(desc) || navigator.onLine === false;
  let title = "Can't reach " + host;
  let text = 'The site might be down, or the address might be wrong.';
  let badge = '🛰️';
  if (code === -1000 || desc === 'ssl') {
    title = "This connection isn't private";
    text = host + " didn't prove it is the real site. Someone could be trying to steal your information. TP Browser stopped loading it.";
    badge = '🔒';
    $('badge').classList.add('warn');
  } else if (offline) {
    title = "You're offline";
    text = 'Check your Wi-Fi or mobile data. TP will load the page when you try again.';
    badge = '📡';
  } else if (code === -2 || /NAME_NOT_RESOLVED/i.test(desc)) {
    title = "Can't find " + host;
    text = 'Check the spelling of the address, or your internet connection.';
    badge = '🔎';
  } else if (code === -8 || /TIMED_OUT/i.test(desc)) {
    title = host + ' is taking too long';
    text = 'The site is slow or not answering right now.';
    badge = '⏳';
  } else if (/BLOCKED_BY/i.test(desc)) {
    title = host + ' refused to open here';
    text = 'This page asked not to be shown inside another page.';
  }
  document.title = title;
  $('badge').textContent = badge;
  $('title').textContent = title;
  $('text').textContent = text;
  $('details').textContent = desc && desc !== 'ssl' ? desc.replace(/^net::/, '') : '';
  const isSsl = code === -1000 || desc === 'ssl';
  if (isSsl) {
    $('retry').hidden = true;
    $('text').textContent = text + ' Use the back button to leave.';
  }
  $('retry').onclick = () => {
    if (/^https?:/i.test(url)) location.replace(url);
  };
  if (offline && /^https?:/i.test(url)) {
    window.addEventListener('online', () => location.replace(url));
  }
})();

