'use strict';
(function () {
  const params = new URLSearchParams(location.search);
  const url = params.get('u') || '';
  const endsAt = Number(params.get('e') || 0);
  let host = url;
  try {
    host = new URL(url).hostname.replace(/^(www|m)\./, '');
  } catch (e) {
    // keep the raw text
  }
  const $ = (id) => document.getElementById(id);
  const cheers = [
    'Future you says thanks.',
    'Small steps add up. Keep going!',
    'You can check it when the timer ends.',
    "You're doing great.",
    'Deep work mode: on.',
  ];
  $('text').textContent = host + ' is paused while Focus mode is on.';
  $('cheer').textContent = cheers[Math.floor(Math.random() * cheers.length)];
  $('back').hidden = history.length < 2;
  $('back').onclick = () => history.back();
  function tick() {
    const left = Math.max(0, endsAt - Date.now());
